local source = "MultiLanguage Classic c51dc2e5141f070f5b92de190521d79e8dccaeab"
local data = WordHunterWoW_QuestDataByFlavor
local function apply(id, targets, passages)
    for _, flavor in ipairs(targets) do
        local languages = data and data[flavor]
        for locale, fields in pairs(passages) do
            local record = languages and languages[locale] and languages[locale][id]
            if record then
                for field, text in pairs(fields) do
                    if not record[field] or record[field] == "" then
                        record[field] = text
                        record[field .. "Source"] = source
                        record[field .. "SourceFlavor"] = "classic"
                    end
                end
            end
        end
    end
end

apply(7849, { "classic", "forever" }, { deDE = { progress = "Wenn Ihr seine Überreste geborgen habt, werde ich sie zu Yayo'jin bringen und sie für eine gebührliche Bestattung vorbereiten lassen.", completion = "Mein geliebter Bruder, wie sehr ich dich vermissen werde...\n\nDanke für Eure Hilfe, {name}. Ihr seid ein wahrer Held für mich." }, enUS = { progress = "When I have his remains, I shall take them to Yayo'jin and have them prepared for a proper burial.", completion = "My dearest brother, how I will miss you...\n\nThank you for your assistance, {name}. You are truly a hero in my eyes." } })
apply(7850, { "classic", "forever" }, { deDE = { progress = "Seid beim Kampf mit den Vilebranch auf der Hut, {name}. Ihre Gedanken sind nicht klar - sie kämpfen bis zum Tod.", completion = "Die dunkle Energie, die die Vilebranch gefügig macht, wurde aufgelöst - für's Erste. Wir müssen bei unserem Kampf gegen das Böse stets wachsam bleiben, denn auch wenn die üble Priesterin vernichtet wurde, so wird doch bald ein anderer ihren Platz einnehmen." }, enUS = { progress = "Be cautious in battling the Vilebranch, {name}. Their minds are clouded - they fight to the death.", completion = "The dark energy that compels the Vilebranch has been lifted - for now. We must remain ever vigilant in our battle against evil, as even if the Vile Priestess is destroyed, another soon takes her place." } })
apply(7861, { "classic", "forever" }, { deDE = { completion = "Das war in der Tat ein lähmender Schlag für die Vilebranch. Ihr sollt reichlich entlohnt werden, {name}." }, enUS = { completion = "A crippling blow to the Vilebranch, indeed. You shall be richly rewarded, {name}." } })
apply(7862, { "classic", "forever" }, { deDE = { completion = "Ihr seid wirklich ein würdiger Kandidat für den neuen Posten, {name}. Nehmt dieses Schmuckstück als Zeichen unserer Anerkennung für Eure harte Arbeit. Ich werde mir sämtliche Bewerbungen nächstes Jahr durchsehen." }, enUS = { completion = "You are indeed a worthy candidate for the new position, {name}. Accept this trinket as a token of our appreciation for your hard work. I will be reviewing all applications next year." } })
apply(7877, { "classic", "forever" }, { deDE = { completion = "Ihr öffnet die Truhe und findet..." }, enUS = { completion = "You open the chest to find..." } })
apply(7905, { "classic", "forever" }, { deDE = { progress = "Ja, kann ich Euch vielleicht behilflich sein? Habt Ihr einen Gutschein zum Einlösen?", completion = "Willkommen beim Dunkelmond-Jahrmarkt! Dieser Gutschein ist gültig für FÜNF, ja, FÜNF Gewinnlose!\n\nHabt Ihr Gewinnlose angesammelt, dann werdet Ihr mit mir sprechen wollen, um sie gegen wertvolle Preise einzutauschen. Je mehr Lose Ihr bekommt, umso mehr Preise könnt Ihr gewinnen. Huzzah!" }, enUS = { progress = "Yes friend, may I help you?  Do you have a voucher that needs redeeming?", completion = "Welcome to the Darkmoon Faire!  This voucher is good for FIVE, yes, FIVE prize tickets!\n\nWhen you accumulate prize tickets, you'll want to speak to me about redeeming them for valuable prizes.  The more tickets you get, the more prizes you can win.  Huzzah!" } })
apply(7907, { "classic", "forever" }, { deDE = { progress = "Wie ich sehe habt Ihr es geschafft ein Set der Bestienkarten zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft das Bestienkartenset zu komplettieren. Das Ihr uns die Karten zurückgebt wird ein Band zwischen Euch und denen des Dunkelmonds schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten als Zeichen unserer Dankbarkeit zu schenken." }, enUS = { progress = "I see that you have managed to complete a deck of beasts!   Congratulations!", completion = "So you have put together a deck of Beasts.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater darkmoon cards as a small token of our appreciation." } })
apply(7926, { "classic", "forever" }, { deDE = { progress = "Ja, kann ich Euch vielleicht behilflich sein? Habt Ihr einen Gutschein zum Einlösen?", completion = "Willkommen beim Dunkelmond-Jahrmarkt! Dieser Gutschein ist gültig für FÜNF, ja, FÜNF Gewinnlose!\n\nHabt Ihr Gewinnlose angesammelt, dann werdet Ihr mit mir sprechen wollen, um sie gegen wertvolle Preise einzutauschen. Je mehr Lose Ihr bekommt, umso mehr Preise könnt Ihr gewinnen. Huzzah!" }, enUS = { progress = "Yes friend, may I help you?  Do you have a voucher that needs redeeming?", completion = "Welcome to the Darkmoon Faire!  This voucher is good for FIVE, yes, FIVE prize tickets!\n\nWhen you accumulate prize tickets, you'll want to speak to me about redeeming them for valuable prizes.  The more tickets you get, the more prizes you can win.  Huzzah!" } })
apply(7928, { "classic", "forever" }, { deDE = { progress = "Ah, Ihr habt das Kriegsherrenkartenset nun vollständig beisammen! Glückwunsch!", completion = "Ihr habt es also geschafft das Kriegsherrenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen." }, enUS = { progress = "I see that you have managed to complete a deck of warlords!   Congratulations!", completion = "So you have put together a deck of Warlords.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater darkmoon cards as a small token of our appreciation." } })
apply(7929, { "classic", "forever" }, { deDE = { progress = "Ah, Ihr habt das Elementarkartenset nun vollständig beisammen! Glückwunsch!", completion = "Ihr habt es also geschafft das Elementarkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen." }, enUS = { progress = "I see that you have managed to complete a deck of elementals!   Congratulations!", completion = "So you have put together a deck of Elementals.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater darkmoon cards as a small token of our appreciation." } })
apply(7937, { "classic", "forever" }, { deDE = { progress = "Dieser Heuhaufen sieht aus wie der aus Eurer Vision.", completion = "Eine rasche Durchsuchung des Heuhaufens bringt eine Schließkassette ans Licht! Es scheint als hättet Ihr Euer Schicksal gefunden!" }, enUS = { progress = "This haystack looks like the one from your vision.", completion = "A quick search of the haystack reveals a lockbox from within it!  It would seem that you have found your fortune!" } })
apply(7945, { "classic", "forever" }, { deDE = { progress = "Dieser Baumstumpf sieht aus wie der aus Eurer Vision.", completion = "Eine rasche Untersuchung des Baumstumpfs bringt eine Schließkassette ans Licht! Es scheint als hättet Ihr Euer Schicksal gefunden!" }, enUS = { progress = "This tree stump looks like the one from your vision.", completion = "A quick search of the tree stump reveals a lockbox from within it!  It would seem that you have found your fortune!" } })
apply(8151, { "classic", "forever" }, { deDE = { completion = "Ich beabsichtige nicht länger selbst zu jagen, jedoch möchte ich {class} unterrichten. Das ist mein Weg des Schicksals.\n\nStellt mit mir einen Talisman des Jägers her -- eine Kollektion von Trophäen gefallener Beute wird Euch an die Versuche und Siege Eurer Vergangenheit erinnern. Letztendlich werde ich den Talisman zwar behalten, Euch dafür aber mit etwas anderem belohnen." }, enUS = { completion = "It is no longer my purpose to hunt, but to teach the {class}.  That is what fate has handed to me.\n\nCraft with me a {class}'s charm -- a collection of trophies from fallen prey that will remind you of your past trials and triumphs.  In the end I will keep the charm, but reward you with something else." } })
apply(8181, { "classic", "forever" }, { deDE = { completion = "So, Ihr habt also mit dem alten Zwerg Ironboot gesprochen und die verlorenen Schrifttafeln von Mosh'aru entdeckt, ja? Dieser sich überall einmischende Schnüffler...\n\nEgal. Es ist zu spät, um diese Welt noch retten zu können.  Hakkar wurde wiedergeboren und seine Macht wächst weiter... tief in dem uralten Königreich der Trolle, Zul'Gurub! Er ist zurück! Und er wird Blut und Terror über die Welt bringen!\n\nIch danke Euch, {name}. Mittels Eurer Hilfe wurde die Rückkehr des Seelenschinders beschleunigt!" }, enUS = { completion = "So, you have been speaking with that old dwarf Ironboot and uncovered the lost Mosh'aru Tablets, have you?  That meddling prospector...\n\nNo matter.  It is too late to save this world.  Hakkar has been reborn, and even now grows in power... deep in the ancient troll kingdom of Zul'Gurub!  He has come!  And he will rule in blood and terror!\n\nThank you, {name}.  Your help has sped the return of the Soulflayer!" } })
apply(8182, { "classic", "forever" }, { deDE = { completion = "Ihr wurdet von Ausgrabungsleiter Ironboot hierher gesandt? Seinesgleichen ist weise, es ist sogar noch weiser Euch zu mir zu senden, weil ich und die zandalarianischen Trolle möglicherweise wissen, wie man den Seelenschinder besiegt.\n\nSprecht mit den Trollen dieser Insel, beherzigt ihre Worte und bereitet Euch auf die Aufgabe vor {name}, bevor Ihr in Blut baden werdet." }, enUS = { completion = "You were sent by the prospector, Ironboot?  His kind are wise, and wiser still to bring you to me, for I and the Zandalarian trolls may know a way to defeat the Soulflayer.\n\nSpeak with the trolls of this isle, heed their words, and prepare yourself, {name}, for the task before you is soaked in blood." } })
apply(8183, { "classic", "forever" }, { deDE = { progress = "{name}, der Gestank einer üblen Seelen umgibt Euch. Wurdet Ihr vom Seelenschinder verflucht?", completion = "Ah, das Herz von Hakkar. Also wurde der Seelenschinder besiegt! Die Welt ist gerettet!\n\n{name}, Euer Dienst für uns kann nicht genug gerühmt werden. Ihr seid wahrlich ein Held!" }, enUS = { progress = "{name}, the reek of an evil soul surrounds you.  Have you been cursed by the Soulflayer?", completion = "Ah, the Heart of Hakkar.  So the Soulflayer has been slain!  Our world is saved!\n\n{name}, your service to us cannot be overstated.  You truly are a hero of this realm!" } })
apply(8231, { "classic", "forever" }, { deDE = { progress = "Seid Ihr erfolgreich gewesen?", completion = "Die Wellenhauer sind nicht einfach zu bezwingen, vor allem nicht in ihrer natürlichen Umgebung, dem Wasser.\n\nIhr habt bewiesen, dass Ihr bereit für die Jagd auf noch tödlichere Beute seid." }, enUS = { progress = "Have you met with success?", completion = "The wavethrashers are not easily defeated, even more so in their watery environment.\n\nYou have proven yourself ready to hunt even deadlier prey." } })
apply(8251, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Staub?", completion = "Gut gemacht, {name}! Ich finde es doch immer wieder beeindruckend, wie überzeugend eine Salve arkaner Geschosse sein kann." }, enUS = { progress = "Have you the dust?", completion = "Well done, {name}!  It never ceases to amaze me how persuasive a volley of arcane missiles can be." } })
apply(8253, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meinen alten Feind besiegt?", completion = "Unglaublich. Der Splitter ist sogar noch mächtiger geworden. Er scheint über all die Jahre die Energie des Drachen absorbiert zu haben.\n\nEs gibt nichts mehr worum ich Euch nun bitten könnte. Meine Fähigkeit das Arkane zu wirken ist mit der Rückkehr dieses Splitters komplett wiederhergestellt. Meine erste Kreation sei die Eure, {name}, und Ihr müsst lediglich wählen..." }, enUS = { progress = "Have you slain my old nemesis?", completion = "Incredible.  The shard has grown as it absorbed the drake's energy over the long years.\n\nThere is no more I can ask of you now.  My full ability to forge the arcane has returned with this shard.  My first creation is yours, {name}, and you have but to choose..." } })
apply(8275, { "classic", "forever" }, { deDE = { completion = "Hervorragend, wieder ein Rekrut, der dem Aufruf gegen die Silithiden gefolgt ist. Willkommen auf Burg Cenarius, {class}. Es freut mich zu sehen, dass unsere Abgesandten auch Helden von Eurem Kaliber erreicht haben. An diesem Ort mangelt es wahrlich nicht an Aufgaben, mit denen Ihr unsere Sache unterstützen könnt. Ich denke, Ihr werdet Euch sehr schnell als unverzichtbarer Verbündeter erweisen." }, enUS = { completion = "Excellent, a new recruit answering the call to arms against the silithid.  Welcome to Cenarion Hold, {class}.  I am pleased to see the words of our emissaries are reaching heroes of your caliber.  You will find no shortage of opportunities to help us in our efforts here and I expect you'll quickly prove to be a valuable ally to our cause." } })
apply(8276, { "classic", "forever" }, { deDE = { completion = "Hervorragend, wieder ein Rekrut, der dem Aufruf gegen die Silithiden gefolgt ist. Willkommen auf Burg Cenarius, {class}. Es freut mich zu sehen, dass unsere Abgesandten auch Helden von Eurem Kaliber erreicht haben. An diesem Ort mangelt es wahrlich nicht an Aufgaben, mit denen Ihr unsere Sache unterstützen könnt. Ich denke, Ihr werdet Euch sehr schnell als unverzichtbarer Verbündeter erweisen." }, enUS = { completion = "Excellent, a new recruit answering the call to arms against the silithid.  Welcome to Cenarion Hold, {class}.  I am pleased to see the words of our emissaries are reaching heroes of your caliber.  You will find no shortage of opportunities to help us in our efforts here and I expect you'll quickly prove to be a valuable ally to our cause." } })
apply(8277, { "classic", "forever" }, { deDE = { progress = "Habt Ihr alle Proben zusammengesammelt? Wir können Noggle jede Minute verlieren!", completion = "Lasst uns die Daumen drücken! Hoffen wir, dass Noggle damit gerettet werden kann!" }, enUS = { progress = "Are you done collecting those samples?  We could lose Noggle any minute now!", completion = "Cross your fingers, friend!  Here's to hoping we can save Noggle!" } })
apply(8280, { "classic", "forever" }, { deDE = { completion = "Ich bin Euch sehr dankbar. Eure Bemühungen, Burg Cenarius und seine Garnison zur schützen, zeugt von wahrer Tapferkeit!" }, enUS = { completion = "You have my sincere gratitude.  Your efforts in helping Cenarion Hold have shown true courage." } })
apply(8283, { "classic", "forever" }, { deDE = { progress = "Ich brauche die Zange der Kreatur als Beweis für Eure Heldentat. Keine Zange, keine Belohnung.", completion = "Ausgezeichnet! Mit dem Tod Totenstachels steht uns der südliche Gebirgszug als strategischer Pfad zum Umgehen der Silithidschwärme wieder offen. Man schätzt Eure Leistung hier sehr." }, enUS = { progress = "I'll need the creature's pincer as proof of the deed.  No pincer, no reward.", completion = "Excellent!  With Deathclasp gone we're free to use the southern mountain range as a strategic path to circumvent the silithid hives.  Your work is greatly appreciated." } })
apply(8284, { "classic", "forever" }, { deDE = { progress = "Das verwüstete Lager werdet Ihr nordwestlich von hier finden. Kommt zu mir zurück, wenn Ihr alle Fragmente gefunden habt.", completion = "Wie ich es mir gedacht habe. Ich kann zwar einige der Worte auf den Schrifttafeln entziffern, jedoch scheinen sie keiner Logik zu folgen oder irgendeine Bedeutung zu haben. Das ist nicht unbedingt ungewöhnlich, da viele Sekten der Twilight-Hammer dafür bekannt sind, ihre Texte zu verschlüsseln. Wir müssen jemanden finden, der sich besser mit solchen Sachen auskennt als wir." }, enUS = { progress = "The ravaged camp can be found northwest of here.  Come back when you have all the fragments.", completion = "Just as I suspected.  I can decipher individual words in the tablets but they appear to be devoid of any logic or meaning.  It's not unknown for Twilight's Hammer sects to use a code to hide the meaning of their texts; we'll have to go to someone who knows more about this sort of thing." } })
apply(8286, { "classic", "forever" }, { deDE = { progress = "Ist Anachronos zurückgekehrt?", completion = "Es ist, wie es sein sollte! Der Eine hat sich erhoben und meine Wache neigt sich dem Ende zu…" }, enUS = { progress = "Has Anachronos returned?", completion = "It is as it should be - the great one has risen. My watch comes to an end..." } })
apply(8290, { "classic", "forever" }, { deDE = { description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, junger {class}. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Warsongschlucht und verteidigt die Feste Silverwing. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, {name} und ich werde Euch belohnen.", objectives = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Warsongschlucht und kehrt zur Schildwache Farsong am Hain der Silverwing zurück." } })
apply(8295, { "classic", "forever" }, { deDE = { description = "Die Wildnis von Ashenvale wird sich der Macht der Horde ergeben, {race}. Nichts, was die Silverwing tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche unseren Fortschritt zu behindern, zunichte macht. Zerstört die Schildwachen der Silverwing und erlangt ein Ehrenabzeichen der Warsong. Kehrt zu mir zurück {name}, wenn Ihr im Besitz eines Ehrenabzeichens seid und ich werde Euch belohnen.", objectives = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Warsongschlucht und kehrt anschließend zu Captain Shatterskull im Mor'shan-Stützpunkt zurück." } })
apply(8305, { "classic", "forever" }, { deDE = { completion = "In der Nähe des Kristalls empfindet Ihr große Trauer. Dieses Gefühl ist so stark, dass Ihr glaubt, jeden Moment das Bewusstsein zu verlieren und an den Folgen der Trauer zu sterben." }, enUS = { completion = "You can feel a great sorrow revolving around this crystal. The force is so powerful that you feel as if you might collapse and die of sadness." } })
apply(8308, { "classic", "forever" }, { deDE = { progress = "Bei den Göttern.", completion = "Nun, jetzt wird mir einiges klar. Solltet Ihr jemals einen Weg nach Ahn'Qiraj finden, haltet Ausschau nach dem guten Brann. Ich befürchte, ohne seinen Affen ist er hilflos." }, enUS = { progress = "Oh dear.", completion = "Well this explains a lot. If you ever find a way into Ahn'Qiraj, keep an eye out for ol' Brann. I'm afraid that he'll be powerless without his monkey." } })
apply(8311, { "classic", "forever" }, { deDE = { progress = "Habt Ihr schon alle Süßigkeiten beisammen? Ich bin traurig, dass ich wegen meinem Kranksein nicht selbst gehen kann, aber zumindest fühle ich mich ein bisschen besser, weil Ihr mir aushelft...", completion = "Wow, Ihr habt sie alle! Ihr seid großartig!\n\nDanke, dass Ihr für mich Süßigkeitensammeln und Streichespielen gegangen seid. Hier, nehmt diese Kürbisdrops - Ihr findet sie bestimmt ganz toll!\n\nGruselige Schlotternächte, {name}!" }, enUS = { progress = "Have you finished trick-or-treating yet?  I'm sad that I can't go because I'm sick, but you helping me out makes me feel a little better...", completion = "Wow, you got them all!  You're awesome!\n\nThank you for trick-or-treating for me.  Here, take these pumpkin treats - I think you'll like them a lot!\n\nHappy Hallow's End, {name}!" } })
apply(8312, { "classic", "forever" }, { deDE = { progress = "Habt Ihr schon alle Süßigkeiten beisammen? Ich bin traurig, dass ich wegen meinem Kranksein nicht selbst gehen kann, aber zumindest fühle ich mich ein bisschen besser, weil Ihr mir aushelft...", completion = "Wow, Ihr habt sie alle! Ihr seid großartig!\n\nDanke, dass Ihr für mich Süßigkeitensammeln und Streichespielen gegangen seid. Hier, nehmt diese Kürbisdrops - Ihr findet sie bestimmt ganz toll!\n\nGruselige Schlotternächte, {name}!" }, enUS = { progress = "Have you finished trick-or-treating yet?  I'm sad that I can't go because I'm sick, but you helping me out makes me feel a little better...", completion = "Wow, you got them all!  You're awesome!\n\nThank you for trick-or-treating for me.  Here, take these pumpkin treats - I think you'll like them a lot!\n\nHappy Hallow's End, {name}!" } })
apply(8313, { "classic", "forever" }, { deDE = { progress = "Habt Ihr etwas über das Rezept erfahren können? Ich hoffe, Ihr behaltet dieses Wissen nicht für Euch selbst!", completion = "Na dann sehen wir mal...\n\nDas sieht recht verständlich aus. Sie haben ihre eigenen Bezeichnungen für einige der Kräuter, aber das dürfte nicht weiter schwer zu entschlüsseln sein. Schaut, ich zeige es Euch!" }, enUS = { progress = "Did you learn the recipe?  You won't keep it to yourself, I hope!", completion = "Let's have a look at that...\n\nThis seems simple enough.  They have their own names for some of the herbs, but those are simple enough to figure out.  Here, let me show you!" } })
apply(8317, { "classic", "forever" }, { deDE = { progress = "Wie steht's mit den Knödeln?", completion = "Ausgezeichnet! Ihr seid meine Rettung! Diese Knödel sind sogar richtig gut. Ich hätte von den Twilight-Hammer eigentlich nicht so etwas Schmackhaftes erwartet." }, enUS = { progress = "How are those dumplings coming along?", completion = "Excellent!  You're a life saver.  These dumplings turned out to be quite good.  Didn't really expect such good taste from the Twilight's Hammer." } })
apply(8318, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Texte?", completion = "Exzellent! Ich werde diese Texte gut verstauen, vielleicht erweisen sie sich später noch als nützlich." }, enUS = { progress = "Did you bring me some texts?", completion = "Excellent!  I'll stash these away, maybe they'll be useful later." } })
apply(8322, { "classic", "forever" }, { deDE = { progress = "Der Kessel ist voller Bier.", completion = "Nachdem Ihr Euch erfolgreich bis ins Gasthaus durchgeschlagen habt, werft Ihr jetzt die Eier in den großen Kessel. Ihr riecht bereits, wie der faulige Gestank die Luft verpestet..." }, enUS = { progress = "The keg is filled with ale.", completion = "Having successfully fought your way inside the inn, you now place the eggs inside the keg.  You can smell the foul odor permeating the air..." } })
apply(8365, { "classic", "forever" }, { deDE = { progress = "Habt Ihr alle 20 Hüte? Ich glaube Euch kein Wort, zeigt sie her. Ich hoffe für Euch, dass sie noch sauber und ganz sind!", completion = "Oh, Ihr seid ein Schatz, auch wenn Ihr etwas länger gebraucht habt, als ich es gewohnt bin. Diese Lieferung wird mir so einiges an Geld einbringen, sobald ich diese Hüte richtig gesäubert und individuell gestaltet habe. Hier habt Ihr etwas für Eure Mühen, Ihr habt Eure Aufgabe mit Bravour erledigt. Ich empfehle Euch allerdings, etwas von dem Geld für ein Bad auszugeben." }, enUS = { progress = "Do you have all 20 hats? I don't believe you, let me see them. They better be in pristine condition!", completion = "Oh you're a darling, even if it did take you longer than I am accustomed to. This shipment should make me quite a bit of money once I've cleaned and personalized these hats. And seeing as I'm always willing to reward work that's well done, here's a little something for you. I suggest that you spend some of it on a bath sweetie." } })
apply(8366, { "classic", "forever" }, { deDE = { completion = "{name}! Ihr seid der Mann!!!\n\nIch bin mir sicher, dass das Kartell mir jetzt wieder freundlicher gestimmt sein wird, nun da Ihr mir mit dem Südmeerabschaum geholfen habt. Lasst mal sehen, womit könnte ich Euch belohnen? Und wenn ich Euch ein paar Münzen gäbe, damit Ihr Euch hier etwas aussucht? Na, seid Ihr damit einverstanden?" }, enUS = { completion = "{name}! You are the man!!!\n\nI'm sure that the Cartel will ease up on me now that you've dealt with those Southsea scum. Let's see, what can I give you as a reward? How about a little coin and you choose from one of these for your trouble?" } })
apply(8373, { "classic", "forever" }, { deDE = { completion = "Ah, es riecht schon fast wieder gut hier. Fast.\n\nIch danke Euch, {name}, Southshore kommt vielleicht ein weiteres Mal über die Schlotternächte hinweg. Hier sind Eure Süßigkeiten, gern geschehen! Solltet Ihr noch mehr Süßigkeiten benötigen, dann könnte Euch eventuell eine Gnomin namens Katrina Shimmerstar in Ironforge noch mehr verkaufen; ich glaube, dass sie sich nur während der Schlotternächte dort aufhält." }, enUS = { completion = "Ah, it almost smells better around here already.  Almost.\n\nThanks to you, {name}, Southshore just might make it through another Hallow's End.  Here's your treats, with my thanks!  If you run out of candy, I think there's a gnome named Katrina Shimmerstar in Ironforge who can sell you more; she's only around during Hallow's End, I believe." } })
apply(8393, { "classic", "forever" }, { deDE = { progress = "Sagt mir, welche Neuigkeiten gibt es von der Front?", completion = "Gute Arbeit, Soldat. Macht so weiter und die Horde wird schon bald die Flucht Richtung Orgrimmar antreten." }, enUS = { progress = "Tell me, what are the news from the front?", completion = "Good work, soldier!  Keep it up and we'll have the Horde running all the way back to Orgrimmar." } })
apply(8394, { "classic", "forever" }, { deDE = { progress = "Sagt mir, welche Neuigkeiten gibt es von der Front?", completion = "Gute Arbeit, Soldat. Macht so weiter und die Horde wird schon bald die Flucht Richtung Orgrimmar antreten." }, enUS = { progress = "Tell me, what are the news from the front?", completion = "Good work, soldier!  Keep it up and we'll have the Horde running all the way back to Orgrimmar." } })
apply(8395, { "classic", "forever" }, { deDE = { progress = "Sagt mir, welche Neuigkeiten gibt es von der Front?", completion = "Gute Arbeit, Soldat. Macht so weiter und die Horde wird schon bald die Flucht Richtung Orgrimmar antreten." }, enUS = { progress = "Tell me, what are the news from the front?", completion = "Good work, soldier!  Keep it up and we'll have the Horde running all the way back to Orgrimmar." } })
apply(8396, { "classic", "forever" }, { deDE = { progress = "Sagt mir, welche Neuigkeiten gibt es von der Front?", completion = "Gute Arbeit, Soldat. Macht so weiter und die Horde wird schon bald die Flucht Richtung Orgrimmar antreten." }, enUS = { progress = "Tell me, what are the news from the front?", completion = "Good work, soldier!  Keep it up and we'll have the Horde running all the way back to Orgrimmar." } })
apply(8410, { "classic", "forever" }, { deDE = { progress = "Was habt Ihr mir mitgebracht, {class}?", completion = "Hey, gut gemacht. Unterhalten wir uns jetzt…" }, enUS = { progress = "What you got for me, {class}?", completion = "Excellent, mon.  Now we be talkin'." } })
apply(8413, { "classic", "forever" }, { deDE = { progress = "Wo sind die Federn, mein Freund?", completion = "Es ist Zeit, dass dieser Troll eine ganze Nacht Ruhe bekommt! Das Geistertotem wird über mich wachen\n\nIch habe eine ganze Weile Dinge gesammelt, vielleicht möchtet Ihr ja was für all' Eure Mühe?" }, enUS = { progress = "Where's the feathers, mon?", completion = "It's about time this troll got a full night's rest!  The spirit totem will watch over me.\n\nI been a long time collectin' things, maybe you want somethin' for all your trouble?" } })
apply(8417, { "classic", "forever" }, { deDE = { completion = "So, Ihr seid also gekommen um meinen Schmerz zu lindern. Ich wünschte, Ihr könntet mich einfach niederstrecken, aber es ist nicht so simpel..." }, enUS = { completion = "So, you have come to alleviate my pain.  I wish you could simply strike me down, but it is not that simple..." } })
apply(8423, { "classic", "forever" }, { deDE = { completion = "Ich brauche keinen Beweis für Eure Taten, {class}. Ich kann es an dem entschlossenen Ausdruck in Eurem Gesicht erkennen." }, enUS = { completion = "I need no proof to know what you have done, {class}.  I can see the determination etched in your expression." } })
apply(8424, { "classic", "forever" }, { deDE = { progress = "Die Schattenanbeter lassen sich nicht so leicht unterkriegen, nicht wahr? Ihr seid jedoch ein {class} und werdet entweder triumphieren oder zumindest bei dem Versuch sterben.", completion = "Ihr habt meinen Schmerz bereits überwältigt und mich geehrt. Ich danke Euch, {class}." }, enUS = { progress = "The shadowsworn are not easily defeated, are they?  But you are a {class}, and you will triumph or perish trying.", completion = "Already you have subdued my pain and honored me.  Thank you, {class}." } })
apply(8460, { "classic", "forever" }, { deDE = { progress = "Nur weiter so, {name}. Wenn Ihr Euch unser Vertrauen verdienen möchtet, dann müsst Ihr Euch erst als würdig beweisen.", completion = "Wir leiden sehr unter den Ereignissen der Vergangenheit. Vielen Dank für Eure Hilfe zum Schutz aller Furbolgs der Holzschlundfeste. Bitte nehmt diese bescheidene Gabe als Zeichen für unsere wachsende Freunschaft an." }, enUS = { progress = "Keep at it, {name}.  If you are to earn our trust, you will need to prove yourself to us.", completion = "We suffer much from the events of the past.  Thank you for what you have done to help protect the Timbermaw.  As a sign of our growing friendship, please accept this humble offering." } })
apply(8461, { "classic", "forever" }, { deDE = { progress = "Wenn Ihr das Vertrauen aller Einwohner der Holzschlundfeste errungen habt, können wir als Gegenleistung für Eure Loaylität vielleicht etwas für Euch tun. Die Furbolgs der Holzschlundfeste vergessen ihre Verbündeten nicht, besonders in dunklen Zeiten wie diesen nicht.", completion = "Ich fühle, dass Ihr erfolgreich gewesen seid. Erfolg... welch nüchternes Wort, wenn man bedenkt, was dafür getan werden musste. Egal, Ihr habt bewiesen, dass Ihr Euch unser Vertrauen verdient habt.\n\nEs kann noch eine Weile dauern, bis die Furbolgs der Holzschlundfeste Euch ohne Feindseligkeit begegnen. Eure Beharrlichkeit wird jedoch jegliches Misstrauen, das meine Brüder Euch gegenüber pflegen, beseitigen. So lange Ihr uns nie betrügt oder Eure Waffen gegen uns richtet, werden wir einen gemeinsamen Weg finden." }, enUS = { progress = "Once you gain the trust of the Timbermaw, I am confident there will be something we will be able to do for you.  The Timbermaw do not forget their allies, especially in dark times such as these.", completion = "I sense that you have achieved victory.  Victory... such a hollow word considering what had to be done.  Regardless, you've proven yourself to be worthy of our trust.\n\nIt may take some time before the Timbermaw welcome you without hostility within the Hold.  Still, your perseverance will erode any suspicion my brethren may have about you.  So long as you never betray us and raise weapons against us, we will find common ground." } })
apply(8462, { "classic", "forever" }, { deDE = { completion = "Ah… die Winde sprachen von solchen wie Euch, Fremde, die ein Bündnis mit den Furbolgs der Holzschlundfeste suchen. Ich heiße Euch willkommen, doch ich muss Euch warnen, denn mein Stamm ist Fremden gegenüber nicht sehr freundlich.\n\nDies sind schwierige Zeiten und wir können nur jenen mit Sicherheit vertrauen, die mit uns Seite an Seite gegen die Verderbnis kämpfen... und sich dabei als vertrauenswürdig erweisen. Jeder, der diese Voraussetzungen nicht erfüllt, wird sofort angegriffen, wenn er es wagen sollte, die Holzschlundfeste zu betreten." }, enUS = { completion = "Ah... I have heard the word on the wind about those not of our tribe who seek to ally themselves with the Timbermaw furbolgs.  I welcome you, but you must be warned that my tribe reacts poorly to strangers.\n\nThese are trying times, and we can only trust those who choose to fight the corruption of the land along side of us... and have proven themselves to us accordingly.  Those who have not done so will be met with open hostility should they enter the Hold." } })
apply(8464, { "classic", "forever" }, { deDE = { completion = "Vielen Dank für Eure Mühen, wie traurig es auch sein mag. Nehmt dies als Zeichen unserer Dankbarkeit.\n\nBitte helft uns auch weiterhin, {name}. Wir haben nur wenige Verbündete, auf die wir uns verlassen können. Ohne Eure Hilfe wäre die Bedrohung gegen unseren Stamm einfach zu groß, als dass wir alleine mit ihr fertig werden könnten." }, enUS = { completion = "Thank you for what you have done, as saddening as it is.  Accept this as a token of thanks.\n\nI would ask of you to please continue helping us, {name}.  We have very few allies on which to call upon, and without your aid, the threats against my tribe would surely be too much for us to handle alone." } })
apply(8465, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, {class}. Ich stehe hier nicht nur als Verteidiger meines Stammes, sondern auch als Sprecher aller Furbolgs der Holzschlundfeste.\n\nUnsere Brüder und Schwestern der Winterfellfurbolgs, welche dieses kalte Land bewohnen, fielen der gleichen Verderbnis zum Opfer, wie die Furbolgs des Teufelswaldes. Wenn Ihr gekommen seid, um den Einwohnern der Holzschlundfeste Eure Hilfe anzubieten, werden wir dieses Angebot mit Freuden akzeptieren." }, enUS = { completion = "Greetings, {class} - I stand guard here as both a speaker for the Timbermaw here in Winterspring and as a defender of the tribe.\n\nOur Winterfall brethren here in this frigid land have fallen under the same corruptive sway as the furbolg of Felwood.  If you've come here offering the Timbermaw furbolgs aid, then we are ready to accept such an offer." } })
apply(8470, { "classic", "forever" }, { deDE = { progress = "Ja {class}, wie kann ich Euch helfen? Ihr geht zwar friedlich umher, dennoch scheint etwas nicht zu stimmen. Ich spüre etwas... etwas Beunruhigendes...", completion = "Dieses Totem... ich erkenne es als eines der Totenwaldfelle wieder, allerdings ist es umhüllt von dem Gestank der Verderbnis. Was auch immer unsere Brüder gegen uns gerichtet haben mag, es befindet sich in diesem Gegenstand.\n\nEs war weise von Euch, es zu uns zu bringen, {name}. Vielleicht können wir mittels Studien und Ritualen herausfinden, was es ist, das den Geist unserer Brüder so verpestet. Vielen Dank, mein Freund - bitte nehmt diese Gabe im Tausch gegen Euren Fund." }, enUS = { progress = "Yes {class}, what can I assist you with?  You walk among us peacefully, though there is assuredly something amiss.  I sense something... something troubling...", completion = "This totem... I recognize it as one of the Deadwood's, but it is thick with the stench of decay.  Whatever foulness has turned our brethren against us is surely present in this object.\n\nYou were wise to bring this to us, {name}.  Perhaps through study and ritual, we can uncover what it is that pollutes the minds of our brethren.  Thank you, friend - please accept these offerings in exchange for your find." } })
apply(8471, { "classic", "forever" }, { deDE = { progress = "{class}, Ihr seid zwar in friedlicher Absicht gekommen, doch spüre ich, dass Euch ernste Angelegenheiten hierher verschlagen haben… Dinge, die sowohl Böses für uns Furbolgs und Euch als {race} verheißen. Was liegt Euch auf der Seele?", completion = "Dieses Ding… seine Form entspricht den Ritualtotems der Winterfellfurbolgs, aber es wurde von irgendwelchen dunklen Kräften verzerrt. Was auch immer unsere Brüder gegen uns gerichtet haben mag, es befindet sich in diesem Gegenstand.\n\nEine höhere Macht hat Euch und diesen Gegenstand zu uns geleitet, {name}. Wir werden ihn aufmerksam untersuchen. Eines Tages vielleicht, werden die Winterfelle aufhören, uns zu bekämpfen.\n\nVielen Dank, mein Freund - bitte nehmt diese Gabe im Tausch gegen Euren Fund." }, enUS = { progress = "{class} - you approach us in a peaceful manner, but I sense that you are here on matters that are grave and severe... for both furbolg and {race} alike.  What have you come to tell us?", completion = "This thing... it is in the shape of a Winterfall Ritual Totem, but it has been twisted by forces I cannot begin to comprehend.  Whatever taint that has set the Winterfall against us is surely present in this object.\n\nDivine wisdom has brought both this and you to us, {name}.  We will study this object intently; perhaps one day, the Winterfall will rage against us no longer.\n\nThank you, friend - please accept these offerings in exchange for your benevolence." } })
apply(8492, { "classic", "forever" }, { deDE = { progress = "Habt Ihr schon die 20 Kupferbarren besorgt?", completion = "Ihr habt es tatsächlich geschafft, Junge! Ich werde Eure Kupferbarren gleich zu den anderen legen und in null Komma nichts werden unsere Schmiede sie in kriegstaugliches Material verwandeln. Wegen solch hilfsbereiten Leuten wie Euch, bin ich stolz darauf, mit Leib und Seele der Allianz zu dienen. Gute Arbeit, Soldat!\n\nSolltet Ihr noch weitere Kupferbarren auftreiben können, bringt sie einfach zu mir." }, enUS = { progress = "Have you collected those twenty bars of copper yet, trooper?", completion = "You did it, lad! We'll get those copper bars onto the pile and put them to good use making the war materiel right away. It's the efforts of people like you that make me proud to serve the Alliance. Good work, soldier!\n\nAnd if you should happen to come across more copper bars, make sure that they find their way to me." } })
apply(8497, { "classic", "forever" }, { deDE = { progress = "Ihr habt etwas für mich?", completion = "Ausgezeichnet. Diese Pakete haben wir wirklich dringend benötigt, {name}. Gute Arbeit." }, enUS = { progress = "You have something for me?", completion = "Excellent!  We were in need of these, {name}.  Thanks." } })
apply(8499, { "classic", "forever" }, { deDE = { progress = "Ich hoffe Ihr seid beim Beschaffen der Thoriumbarren, über die wir vorher gesprochen haben, erfolgreich gewesen.", completion = "Vielen Dank, {class}! Danke! Das sind wieder zwanzig weniger und nur noch eine unzählbare Menge mehr. Die Allianz steht in Eurer Schuld und Eure Bemühungen werden nicht unbelohnt bleiben. Sprecht wieder mit mir, wenn Ihr weitere Thoriumbarren beschafft habt." }, enUS = { progress = "I do so hope that you have been successful in gathering the thorium bars that we spoke of earlier.", completion = "Oh thank you, {class}! Thank you! That's twenty down and an incalculable amount to go. You have the gratitude of the Alliance, and your efforts shall not go unrewarded. Speak to me again should you come across more thorium bars." } })
apply(8501, { "classic", "forever" }, { deDE = { progress = "Ihr wollt mir etwas mitteilen, {name}?", completion = "Exzellente Arbeit, {name}. Eure Leistungen beim Angriff auf den Bau des Ashischwarms wurden zur Kenntnis genommen." }, enUS = { progress = "You wish to tell me something, {name}?", completion = "Excellent work, {name}.  Your part in the attack on Hive'Ashi has been noted." } })
apply(8502, { "classic", "forever" }, { deDE = { progress = "Ihr habt etwas, das Ihr mir erzählen wollt, {class}?", completion = "Ausgezeichnete Arbeit, {name}. Die Silithiden werden ohne ihre Arbeiter Schwierigkeiten haben, all die Schäden zu reparieren, die ihre Baustruktur erlitten hat." }, enUS = { progress = "You have something to tell me, {class}?", completion = "Excellent work, {name}.  Without their workers, the silithid will have a hard time repairing any damage inflicted to their hive's structure." } })
apply(8503, { "classic", "forever" }, { deDE = { progress = "Es ist nicht wahr! Ich habe noch nie Würgetang von den Stapeln hier entwendet. Man könnte natürlich versucht sein, wenn man bedenkt, dass es ein Mittelchen von qasi universeller Nützlichkeit ist. *hüstel* Ihr habt nicht zufällig den Würgetang bei Euch, von dem wir einst gesprochen haben?", completion = "Hurra! Das sind zwanzig weniger. Ihr seid der Größte. Ich packe diese hier schnell weg, bevor sie vertrocknen. Soviel Würgetang und so wenig Zeit!\n\nNochmals danke, {class}!" }, enUS = { progress = "It's not true! I'd never skim any stranglekelp off the top of the stacks here. One might be tempted to though considering that it's practically a panacea of utilitarian usefulness. *cough* You don't happen to have that stranglekelp we discussed earlier?", completion = "Hooray! That's another twenty down. You're the best. I suppose that I should get these all packed away before they wither. So much stranglekelp, so little time!\n\nThanks again, {class}!" } })
apply(8505, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den lila Lotus, nach dem ich verlangt habe?", completion = "Eure Beteiligung wird hoch geschätzt, {class}. Wir können das ruchlose Vordringen der Silithiden und was auch immer für eine Kraft sie vorantreiben mag, nur mit vereinten Kräften zurückschlagen. Sogar die Horde sammelt ihren eigenen Vorrat an lila Lotus an. Solltet Ihr noch mehr finden, kommt bitte hierher zu mir zurück." }, enUS = { progress = "Do you have the purple lotus herbs that I requested?", completion = "Your contribution is greatly appreciated, {class}. It is only through the combined efforts of all that we shall be able to repel the ruthless advance of the silithid and whatever force is driving them forth. Even the Horde is amassing their own collection of purple lotus. Should you come across more, please return to me here." } })
apply(8509, { "classic", "forever" }, { deDE = { progress = "Was ist? Sprecht schon, {class}! Habt Ihr die Ladung an Arthas' Tränen, nach denen ich verlangt habe, denn schon beisammen?", completion = "Gute Arbeit, {class}. Ich muss sagen, dass ich angenehm überrascht bin. Ihr würdet es mir nicht glauben, wieviele Leute hier schon vorbeigekommen sind, mir Ihre Hilfe anboten haben und dann nie zurückgekehrt sind. Lasst mich die Pflanzen nur eben in eine Kiste schaffen und Euren Namen vermerken, dann können wir noch einmal darüber sprechen, wieviele Pflanzen ich noch benötige." }, enUS = { progress = "What's that? Speak up, {class}! Have you got that shipment of Arthas' Tears I asked for?", completion = "Good work, {class}. I must say that I'm pleasantly surprised. You would not believe the number of people that have come by, offering to help, but never returning. Let me just get those into a crate and tallied with your name on it, and then we can talk again about whether I need anymore of those plants." } })
apply(8515, { "classic", "forever" }, { deDE = { progress = "Ist das dickes Leder, das Ihr da bei Euch tragt, {class}? Ja? Ich kann es gar nicht erwarten! Alle werden so zufrieden mit uns sein, meint Ihr nicht?", completion = "Oh, ich habe gewusst, dass Ihr es schafft, {class}! Ich wusste es einfach! Ich werde alles so schnell wie möglich in die richtigen Hände überantworten. Nun lasst uns mal sehen. Hmm, wie es aussieht, geht es voran. Gebt mir einen Moment Zeit, um alles zusammenzuzählen und zu sehen, ob wir noch mehr benötigen. Falls dem so ist, seid doch so gut und zieht nochmal los!" }, enUS = { progress = "Is that the thick leather you have there in your pack, {class}? Is it? I can't wait for you to hand it over! Everyone is going to be so pleased with us don't you think?", completion = "Oh, I knew you could do it, {class}, I just knew it! I'll get these into the right hands as soon as I can. Now, let's see here. Hmm, looks like our tally is coming along rather nicely. You should check back with me in just a moment once I'm done counting to see if we need more.  Cuz if we do, you're the one I want out there gathering it up for me!" } })
apply(8517, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die zwanzig Leinenverbände, die ich benötige, {class}?", completion = "Eure heutige Spende, wird vielen Soldaten zugute kommen, {class}. Ich werde mich persönlich darum bemühen, dass die Allianz von Euren Anstrengungen erfährt. Gebt mir einen Moment Zeit, um die Verbände zu verstauen und meine Liste zu aktualisieren. Sprecht mich später ruhig wieder an, vielleicht brauche ich noch mehr.\n\nMöge Elunes Licht auf Euch herab scheinen, {race}!" }, enUS = { progress = "Do you have the twenty linen bandages that I require, {class}?", completion = "Many are the soldiers that will benefit from your contribution here today, {class}. I shall see to it personally that the Alliance is made aware of your efforts. Allow me a moment to store these bandages properly and update my count, and then you should check back with me to see if I am in need of more.\n\nMay the Light of Elune shine upon you, {race}!" } })
apply(8519, { "classic", "forever" }, { deDE = { completion = "Nach Staghelms Verrat sammelte ich die Bruchstücke des Szepters der Sandstürme ein und kam hierher zurück. Ich wollte den Szepter auf jeden Fall vor denjenigen beschützen, die danach streben würden, um unserer Welt Schaden zuzufügen - folglich wurde der Bund der Drachenschwärme ins Leben gerufen.\n\nEin Szepter, der unter den vier mächtigen Aspekten aufgeteilt werden würde, sollte für diejenigen, die vorsätzlich nach Chaos suchten, fast unmöglich wiederzuerlangen sein... so dachte ich zumindest. Was für ein Narr ich doch war. Noch heute verfolgt mich diese verfluchte Tragödie." }, enUS = { completion = "After Staghelm's betrayal, I gathered the shattered pieces of the Scepter of the Shifting Sands and returned here. I had every intention of protecting the scepter from those that would seek to use it to cause harm to our world - thus was born the charge of the Dragonflights.\n\nA scepter divided amongst the four mighty Aspects would prove to be nearly impossible to restore for those willfully seeking chaos... or so I thought. What a fool I was. Even now I am hunted by that cursed flight." } })
apply(8520, { "classic", "forever" }, { deDE = { progress = "Hallo {class}, konntet Ihr schon die zwanzig Seidenverbände besorgen?", completion = "Ihr habt es tatsächlich geschafft, {class}! Dank Euch sind wir wieder einen Schritt weiter gekommen. Gebt mir etwas Zeit, um Eure Seidenverbände einzulagern. Vielleicht können wir uns danach noch ein wenig unterhalten?" }, enUS = { progress = "Hello, {class}, have you been able to get those twenty silk bandages yet?", completion = "{class}, you did it! Thanks to you we are another step closer to achieving our goal with silk bandages. I'll get them stored away, and then we can talk more if you like." } })
apply(8522, { "classic", "forever" }, { deDE = { progress = "Die Tage verstreichen und wir machen noch immer weiter. {class}, habt Ihr die Runenstoffverbände?", completion = "Eure Beharrlichkeit, was diese Aufgabe angeht, wird nicht unbelohnt bleiben, {class}. Ich werde diese Verbände eben verstauen. Danach sollten wir uns über die Möglichkeit unterhalten, dass Ihr vielleicht noch weitere Runenstoffverbände einsammelt." }, enUS = { progress = "The days pass one after the other, and still we go on. {class}, have you those runecloth bandages?", completion = "You are to be commended, {class}, for your perseverance in this task. I shall put these bandages away, and then I should like to talk to you again about the possibility of your collecting even more runecloth bandages." } })
apply(8524, { "classic", "forever" }, { deDE = { progress = "Wieviel kann ich darauf verwetten, dass Ihr bereits mit all den benötigten Regenbogenflossenthunfischen wieder da seid, {class}?", completion = "Zwei für die Allianz, einer für mich, zwei für die Allianz, einer für mich. Hey, gute Arbeit, Meister. Ihr seid ja ein richtiger Gewinn für unseren Laden. So, wie ich das sehe, werden wir wohl noch eine ganze Menge mehr Thunfisch brauchen. Warum zieht Ihr nicht schonmal los und treibt noch mehr Fische auf? Mein Magen knurrt schon wieder vor Appetit." }, enUS = { progress = "I'm willing to lay odds that you've returned with all of that rainbow fin albacore we were talking about before, right, {class}?", completion = "Two for the Alliance, one for me, two for the Alliance, one for me. Hey there, fishmonger, excellent work. I can see that you're going to be a real credit to the club. Looks to me like we probably need more of that albacore though. Why don't you head on out and rustle up a mite more. I can hear my stomach rumbling already." } })
apply(8526, { "classic", "forever" }, { deDE = { progress = "Habt Ihr jetzt schon all die gerösteten Raptoren?", completion = "Hey, das ist ja klasse! Danke für all das vebrannte Tierfleisch, {class}. Ich werfe es einfach mal drüben auf den Haufen. Irgendjemand wird sich früher oder später schon darum kümmern. Ich nehme an, dass Ihr mir noch mehr Fleisch bringen werdet, sofern Ihr etwas Zeit übrig habt?" }, enUS = { progress = "So do you have all of that roast raptor yet?", completion = "Gee, that's swell. Thanks for bringing me all of this burnt animal flesh, {class}. I'll just put it onto the pile over there. I'm sure that someone will take care of it. I suppose if you have some time on your hands that you might want to bring me more?" } })
apply(8528, { "classic", "forever" }, { deDE = { progress = "Es freut mich, dass Ihr so rasch mit den benötigten Tüpfelgelbschwänzen wieder da seid.", completion = "Habt Dank, für Eure Spende, {class}. Sie kommt genau zur rechten Zeit! Unsere Soldaten werden jetzt sicherlich genug zu essen haben. Lasst mich nur eben den Fisch ordnungsgemäß verstauen, dann können wir uns vielleicht über einen weiteren Schwung Fische unterhalten?" }, enUS = { progress = "I am confident that you are returning so soon with the spotted yellowtail we discussed.", completion = "Thank you for this gift, {class}, and in such a timely manner as well. Our soldiers will surely not lack for something to eat. Just let me get these fish stored away properly and then you and I can discuss a second haul if you're willing." } })
apply(8532, { "classic", "forever" }, { deDE = { progress = "Ich hoffe, dass das die zwanzig Kupferbarren sind, die Ihr da bei Euch tragt, {class}.", completion = "Diese Barren werden ihren Zweck erfüllen und danke, dass Ihr sie nicht poliert habt. Es lohnt sich nicht, sie extra schön aussehen zu lassen, da sie ohnehin zu Kriegsgeräten aller Art verarbeitet werden. Ich kümmere mich um ihre Einlagerung und werde anschließend sicherstellen, dass sie die richtige Verwendung finden. Sprecht mich später noch einmal an, falls Ihr weitere zwanzig Barren spenden wollt." }, enUS = { progress = "I hope that's the twenty copper bars you have there with you, {class}.", completion = "These bars will do, and thanks for not shining them. No sense in making them pretty when they're going to be mangled for whatever materiel needs to be built for the war. I'll take care of putting them on the stacks, and I'll make sure that they are put to proper use. Speak to me again if you're interested in bringing in another twenty." } })
apply(8539, { "classic", "forever" }, { deDE = { progress = "Ihr habt etwas, das Ihr mir erzählen wollt, {class}?", completion = "Ausgezeichnete Arbeit, {name}. Ihr sein ein wertvoller Verbündeter." }, enUS = { progress = "You have something to tell me, {class}?", completion = "Excellent work, {name}.  You're a worthy ally." } })
apply(8542, { "classic", "forever" }, { deDE = { progress = "Wieviele Zinnbarren haben wir denn hier, {class}? Vielleicht sollte ich mir nach dem Krieg mal jemanden suchen, der mir das Zählen beibringen könnte.", completion = "Nun, das scheint die richtige Anzahl an Zinnbarren zu sein. Versucht ja nicht mich reinzulegen, {class}! Vom Zählen kriege ich immer heftige Kopfschmerzen. Ich werde diese Barren erst einmal gut verstauen und Ihr seht zu, dass Ihr noch weitere Barren ergattern könnt." }, enUS = { progress = "How many tin bars do you have there, {class}? After the war I think I'm going to need someone to teach me how to count.", completion = "Well, I guess that looks like the right number of tin bars. Don't try to fool me, {class}! Counting makes my skull hurt. Now I go and put these bars on the stack and you go out and bring me back more of the same." } })
apply(8544, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die von mir benötigten Bestandteile gesammelt?", completion = "Ich werde diese Schulterstücke aus dem Material, das Ihr mir gebracht habt, und den Schuppen der gefallenen Qirajifeinde herstellen, Sterblicher. Mögen sie Euch den Schutz geben, den Ihr braucht, und möge ihr Anblick unseren Feinden Furcht einflößen." }, enUS = { progress = "Have you collected the components I require?", completion = "From the materials you bring and from the scales of our fallen Qiraji foes I make you these pauldrons, mortal.  May they grant you the protection you need and may the sight of them strike fear into our enemies." } })
apply(8545, { "classic", "forever" }, { deDE = { progress = "Es wäre wirklich toll, wenn wir all die Mithrilbarren hätten, die für die Kriegsanstrengungen von Ahn'Qiraj benötigt werden. Seid ihr deswegen zurück? Habt Ihr meine Barren?", completion = "Das ist schon mal ein guter Anfang, {class}. Das sind wieder zwanzig Barren, die ich verstauen und von der Liste streichen kann. Macht Euch keine Sorgen um deren Verwendung, daraus wird hochwertiges Kriegsmaterial hergestellt werden.\n\nSchaut wieder bei mir vorbei, denn wie es aussieht, werden wir noch eine ganze Reihe weiterer Mithrilbarren brauchen." }, enUS = { progress = "It sure would be nice to be havin' all of the mithril bars that we be needin' for the Ahn'Qiraj war effort. Is that why you be back, mon? You got my bars?", completion = "This be a good start for you an me, {class}. That be another twenty mithril bars that I can be puttin' on the stacks an checkin' off of the list. It all gonna be put to good use makin' the war materiel.\n\nBe makin' sure that you check back in with me 'cuz you know it be lookin' like we gonna need even more of those mithril bars." } })
apply(8549, { "classic", "forever" }, { deDE = { progress = "Schon wieder zurück mit den Friedensblumen, {class}?", completion = "Somit bringen uns unsere Bemühungen dem Kriegsbeginn immer näher. Danke für die harte Arbeit, die Ihr beim Sammeln der Friedensblumen geleistet habt, {class}. Ich versichere Euch, dass alles einem guten Zweck zukommt und dass Eure Unterstützung nicht ungeachtet bleibt, {name}. Sollte Euch danach sein, so bringt mir jederzeit noch mehr dieser Blumen. Bis dahin, möge die Erdenmutter Euch leiten." }, enUS = { progress = "Back so soon with the peacebloom, {class}?", completion = "And so our efforts push us that much closer to war. Thank you for your hard work in gathering this peacebloom {class}. I assure you that it will go to good use, and that your contribution has been noted {name}. Should you find yourself willing, please return to me again with more of the flowers. Until then, may the Earth Mother guide you." } })
apply(8551, { "classic", "forever" }, { deDE = { progress = "Ahoi, {name}! Habt Ihr Gorlash finden können? Die Truhe war mein Lieblingsstück und sie hatte ein Geheimfach, mit meinen größten Schätzen.", completion = "Ihr habt sie gefunden! O, was für ein wunderbarer Tag! Ich danke Euch, {name}. Dass ich meine Truhe wiederbekommen habe, beruhigt mich ein wenig.\n\nAber meine Rache ist noch nicht vollständig..." }, enUS = { progress = "Ahoy, {name}!  Did you find Gorlash?  That chest was my favorite, and it has a hidden compartment that held my greatest treasures!", completion = "You found it!  Oh happy day, this is!  Thank you, {name}.  Getting back my chest cools some of the fire in me.\n\nBut my revenge isn't complete..." } })
apply(8552, { "classic", "forever" }, { deDE = { progress = "Hallo. Haben wir geschäftlich miteinander zu tun?", completion = "Ihr habt meine Schärpe wiedergefunden? Dann... müsst Ihr Mok'rash den Meeresriesen getötet haben! Hurra!\n\nIch freue mich, dass dieser räudige Schurke tot ist - Mok'rash war einer von drei Meeresriesen, die meine Schiffe zerstört und meine Crew umgebracht haben.\n\nDrei Mal.\n\nIhr seid ein {class} von Ehre, {name}." }, enUS = { progress = "Hello.  Do you have business with me?", completion = "You recovered my sash?  Then...you must have killed Mok'rash the sea giant!  Hooray!\n\nI'm glad the scurvy villain's dead - Mok'rash was one of three sea giants who smashed my ships and killed my crew.\n\nThree times.\n\nYou are a {class} of worth, {name}." } })
apply(8553, { "classic", "forever" }, { deDE = { completion = "Hallo hallo, {name}. Der Käpt'n sagte mir, Ihr wolltet hinter Negolash her, ja?" }, enUS = { completion = "Hello hello, {name}.  Captain told me you're going after Negolash, eh?" } })
apply(8554, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meinen Entersäbel bekommen können, {name}?", completion = "Ihr habt meinen Entersäbel von Negolash bekommen! Ich kann mein Glück kaum fassen, {name}! Durch Euch hat sich das Glück mir wieder zugewandt, da könnt Ihr Euch sicher sein!\n\nIch danke Euch! Sollte ich jemals wieder ein neues Schiff bekommen und Ihr ein wenig die Meere befahren wollen, dann seid Ihr selbstverständlich mein Ehrengast." }, enUS = { progress = "Did you get my cutlass, {name}?", completion = "You got my cutlass from Negolash!  I can't believe my fortune, {name}!  Meeting you has turned my luck to the better, make no mistake there!\n\nThank you!  And if I ever get a new ship and you're looking to sail the seas, you would be my honored guest." } })
apply(8561, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, {name}?", completion = "Ihr seid erfolgreich gewesen! Das Flüstern der Zwillingsimperatoren ist verstummt.\n\nNehmt dies als Belohnung. Der bloße Anblick hiervon wird Furcht in die Herzen der Qiraji treiben... es soll sie an ihre gefallenen Anführer erinnern und an den Sterblichen, der sie niederstreckte." }, enUS = { progress = "Did you bring me the components I asked for, {name}?", completion = "You've succeeded!  The whispers from the Twin Emperors have ceased.\n\nTake this as a reward.  The mere sight of it will strike fear in the hearts of the Qiraji... it shall remind them of their fallen leaders and of the mortal that slew them." } })
apply(8562, { "classic", "forever" }, { deDE = { progress = "Der furchtbare C'Thun wartet ruhend in seiner Behausung in Ahn'Qiraj.", completion = "Ich habe nicht erwartet, dass Ihr von Eurer Unternehmung zurückkehrt, {name}.\n\nIhr habt eine größere Vorsehung erfüllt als die der meisten sterblichen Wesen.\n\nIndem Ihr C'Thun bezwungen habt, habt Ihr nicht nur ganz Azeroth gerettet, sondern auch kosmische Ereignisse in Gang gesetzt, die weit über Eurem Vorstellungsvermögen liegen.\n\nNehmt diese Brustplatte als Zeichen des Ruhms und der Bürde an, die Euch in Folge Eurer Taten erwarten werden.\n\nMöge ihre Macht bei Euren zukünftigen Herausforderungen mit Euch sein, Göttertöter!" }, enUS = { progress = "At his dwelling in Ahn'Qiraj, dread C'Thun awaits in slumber.", completion = "I did not expect you to return from your attempt, {name}.\n\nYou've fulfilled a destiny greater than that of most immortal beings.\n\nBy slaying C'Thun you've not only saved all of Azeroth, you've also tipped the scales of cosmic events beyond your comprehension.\n\nAccept this breastplate as a symbol of the glory and burden that will come as a consequence of your actions.\n\nMay its power aid you in the challenges that await you, god-slayer!" } })
apply(8573, { "classic", "forever" }, { deDE = { progress = "Es ist unsere beste Absicht, unsere treuesten Verbündeten gut mit Ausrüstung zu versorgen, {name}.", completion = "Gute Arbeit, {name}. Bitte nehmt dies im Namen des Zirkels des Cenarius an. Ihr habt es Euch wahrhaftig verdient!" }, enUS = { progress = "It's in our best interest to keep our most loyal allies well geared, {name}.", completion = "Great work, {name}.  Please accept this on behalf of the Cenarion Circle.  You've certainly earned it, friend!" } })
apply(8580, { "classic", "forever" }, { deDE = { progress = "Ihr wollt doch nicht, dass Pele'keiki böse wird. Ihr macht Pele'keiki glücklich, wenn Ihr ihm schon ganz bald ganz viele Feuerblüten bringt.", completion = "{class}! Pele'keiki ist dank Euch sehr glücklich. Er wird diese Feuerblüten in eine Kiste packen, damit sie frisch bleiben. Aus all diesen Pflanzen werden sie sicherlich eine ganze Menge gutes Kriegsmaterial herstellen. Kommt zurück, falls Ihr noch mehr davon gefunden habt. Pele'keiki kann davon nicht genug kriegen." }, enUS = { progress = "You not want to make Pele'keiki mad. You make Pele'keiki happy by bringing him lots of firebloom, real soon.", completion = "{class}! Pele'keiki happy for now. Pele'keiki take all that firebloom and put it in box so it stay fresh. Pele'keiki be seein' to it that all the firebloom bein' made into good stuff for the war. And if you be gettin' anymore, you come see Pele'keiki fast. Pele'keiki prolly be needin' more." } })
apply(8582, { "classic", "forever" }, { deDE = { progress = "Schon wieder mit dem benötigten lila Lotus zurück, {class}? Es ist entscheidend, dass Ihr so schnell wie möglich handelt, da sonst all mein Bestreben hier umsonst war.", completion = "Ein beachtlicher Erfolg, {class}. Ich werde diese Pflanzen für Ihre endgültige Verwendung vorbereiten und Eure Spende entsprechend vermerken. Erst danach kann ich den lila Lotus ordnungsgemäß einlagern. Was Euch betrifft: Wenn Ihr noch etwas Zeit habt, könnte ich noch mehr lila Lotus gebrauchen. In diesem Fall meldet Euch einfach wieder bei mir." }, enUS = { progress = "Returned already with the purple lotus that I have requested, {class}? It is critical that you do so in as timely as fashion as possible lest all that I am attempting here come to naught.", completion = "A commendable effort, {class}. I will measure these specimens for their appropriate usage and note your contribution. The purple lotus will then need to be properly stored until I am ready for them. As for you, if you are still available I should imagine that I'll still need more purple lotus. Please check back with me in a moment." } })
apply(8588, { "classic", "forever" }, { deDE = { progress = "Solltet Ihr nur zum Plaudern hier sein, dann habe ich keine Zeit für Spielchen, {class}. Es gibt zu viele Stapel schweren Leders, die noch ausgehärtet werden müssen. Kommt wieder, wenn Ihr mindestens zehn für mich beisammen habt.", completion = "Oh, Ihr habt also das schwere Leder, das ich benötige. Eure Klinge ist wirklich scharf, {class}; das sind gute Häute! Da wir uns jetzt zu verstehen scheinen, werde ich dafür sorgen, dass Eure Beisteuerung einer angebrachten Verwendung zu Gute kommt. Solltet Ihr über noch mehr schweres Leder stolpern, dann bringt es zu mir." }, enUS = { progress = "I've got no time for games if you're just here to jibber-jabber, {class}. There are too many stacks of heavy leather that need curing. Come back when you have at least ten for me.", completion = "Oh, so you do have the heavy leather I needed. Your blade is sharp indeed, {class}; these are good skins! Now that we've gotten off on the right foot with one another I'll make sure that your contribution is put to good use. And if you happen to come across more heavy leather, bring it my way." } })
apply(8590, { "classic", "forever" }, { deDE = { progress = "{class}, seid Ihr schon wieder mit den angeforderten zehn Einheiten dicken Leders zurück?", completion = "Gute Arbeit, {class}. Dieses dicke Leder wird sicherlich eine gute Verwendung bei der Rüstungsherstellung oder der Panzerung unserer Zeppeline finden. Ihr habt meinen Dank und den der Horde redlich verdient. Falls Ihr auf Euren Reisen noch mehr dickes Leder auftreiben könnt, besucht mich doch. Alles Gute!" }, enUS = { progress = "{class}, have you returned so soon with the ten thick leather that we discussed?", completion = "Good work, {class}. I'm sure that these thick leather skins will be put to use reinforcing zeppelins and making all manner of armor and weaponry. You have my thanks, and that of the Horde. Come back again if you come across more thick leather in your travels, and luck be with you." } })
apply(8592, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, {name}?", completion = "Ihr seid erfolgreich gewesen! Das Flüstern der Zwillingsimperatoren ist verstummt.\n\nNehmt dies als Belohnung. Der bloße Anblick hiervon wird Furcht in die Herzen der Qiraji treiben... es soll sie an ihre gefallenen Anführer erinnern und an den Sterblichen, der sie niederstreckte." }, enUS = { progress = "Did you bring me the components I asked for, {name}?", completion = "You've succeeded!  The whispers from the Twin Emperors have ceased.\n\nTake this as a reward.  The mere sight of it will strike fear in the hearts of the Qiraji... it shall remind them of their fallen leaders and of the mortal that slew them." } })
apply(8600, { "classic", "forever" }, { deDE = { progress = "Ihr werdet doch wohl nicht so lange brauchen, um mir 10 Einheiten unverwüstliches Leder zu bringen! Vielleicht solltet Ihr noch einmal Euer Messer schleifen? Oder vielleicht bin ich im Unrecht und Ihr habt das Leder bereits in Eurem Rucksack?", completion = "Nun gut, es scheint als wäre das nur eine vorübergehende Arbeit für Euch, da einige Ränder dieser Häute etwas zerfetzt aussehen. Egal, die Aufgabe wurde erfüllt und Ihr habt Euch Eure Gegenleistung verdient. Ich werde Euren Namen neben dem Leder notieren; ich bin mir sicher, dass die Horde Eure Bemühungen zu schätzen wissen wird. Solltet Ihr auf einen weiteren Stapel unverwüstlichen Leders stoßen, dann bringt ihn bitte schnellstens zu mir." }, enUS = { progress = "It couldn't possibly be taking you this long to slice off ten rugged leather for me! Perhaps you should sharpen your skinning knife? Or, perhaps I am mistaken and you have them there in your pack?", completion = "Very well, it appears you've done a fairly decent job of it, though some of those skins look a bit ragged about the edges. No matter, the task is completed, and you have earned your reward. Should you come across another stack of rugged leather, be sure to bring them to me posthaste." } })
apply(8603, { "classic", "forever" }, { deDE = { progress = "Der furchtbare C'Thun wartet ruhend in seiner Behausung in Ahn'Qiraj.", completion = "Ich habe nicht erwartet, dass Ihr von Eurer Unternehmung zurückkehrt, {name}.\n\nIhr habt eine größere Vorsehung erfüllt als die der meisten sterblichen Wesen.\n\nIndem Ihr C'Thun bezwungen habt, habt Ihr nicht nur ganz Azeroth gerettet, sondern auch kosmische Ereignisse in Gang gesetzt, die weit über Eurem Vorstellungsvermögen liegen.\n\nNehmt diese Gewänder als Zeichen des Ruhms und der Bürde an, die Euch in Folge Eurer Taten erwarten werden.\n\nMöge ihre Macht bei Euren zukünftigen Herausforderungen mit Euch sein, Göttertöter!" }, enUS = { progress = "At his dwelling in Ahn'Qiraj, dread C'Thun awaits in slumber.", completion = "I did not expect you to return from your attempt, {name}.\n\nYou've fulfilled a destiny greater than that of most immortal beings.\n\nBy slaying C'Thun you've not only saved all of Azeroth, you've also tipped the scales of cosmic events beyond your comprehension.\n\nAccept these vestments as a symbol of the glory and burden that will come as a consequence of your actions.\n\nMay their power aid you in the challenges that await you, god-slayer!" } })
apply(8604, { "classic", "forever" }, { deDE = { progress = "Ah, {class}, seid Ihr schon wieder mit den Wollverbänden zurück?", completion = "Ihr habt meinen Dank und den der Horde redlich verdient, {class}! Solltet Ihr noch mehr Wollverbände spenden wollen, zögert nicht lange und kommt zu mir. Auf bald. Mögen Eure Vorfahren über Euch wachen!" }, enUS = { progress = "Ah, {class}, have you returned so quickly with the wool bandages?", completion = "You have my thanks, {class}, and the gratitude of the Horde. If you come across more wool bandages bring them to me here should you wish to further contribute to the war effort. Until then, may your ancestors watch over you!" } })
apply(8607, { "classic", "forever" }, { deDE = { progress = "Enttäuscht mich nicht, {class}! Kommt so schnell wie möglich hierher mit den angeforderten Magiestoffverbänden zurück.", completion = "Überraschend, dennoch akzeptabel. Vielleicht habe ich Eure 'Fähigkeiten' ein wenig unterschätzt, {class}. Vielleicht. Wie auch immer, Ihr habt eine mehr als einfache Aufgabe erfolgreich ausgeführt und ich nehme an, man wird Euch eine weitaus größere Belohnung zusprechen, als Ihr sie eigentlich verdient hättet. Lasst Euch das nicht gleich zu Kopfe steigen. Wenn Ihr Euch wirklich beweisen wollt, solltet Ihr wieder losziehen und mir eine weitere Ladung Magiestoffverbände bringen!" }, enUS = { progress = "Do not fail and make me look bad, {class}! Return here as quickly as possible with the mageweave bandages we discussed.", completion = "Surprising, yet acceptable. Perhaps I underestimated your 'abilities', {class}. Perhaps. You completed a very simple task, and for doing so you are to be rewarded out of proportion. But don't let it go to your head. If you really want to prove yourself you should get out there and bring me another bundle of mageweave bandages." } })
apply(8609, { "classic", "forever" }, { deDE = { progress = "Der Krieg naht, {class}. Ich bin Euch sehr dankbar für Eure Hilfe. Habt Ihr die Runenstoffverbände von denen wir gesprochen haben?", completion = "Ihr seid ein Segen für die Horde, {class}. Eure Bemühungen werden von uns sehr geschätzt und sie sind mehr als willkommen! So, jetzt muss ich erst einmal die frischen Verbände verstauen und die neuesten Bestandszahlen ermitteln. Falls Ihr noch mehr Runenstoffverbände sammeln wollt, könnt Ihr sie mir später einfach vorbeibringen." }, enUS = { progress = "The war comes soon, I think, {class}. I thank you for your time and effort devoted to helping with our gathering tasks. Do you return because you have obtained the runecloth bandages that we spoke of before?", completion = "You are a credit to the Horde, {class}. Thank you for your efforts; they are appreciated! I'll have to pack these fresh bandages away and take another count to see how far along we are to our goal. If you'd like you could gather more runecloth bandages and return them to me here." } })
apply(8613, { "classic", "forever" }, { deDE = { progress = "Schon wieder zurück mit den Tüpfelgelbschwänzen, {class}? Habt Ihr auch nicht vergessen sie zu kochen? Wir setzen unseren Soldaten keinen rohen Fisch bei der Gluthitze vor, die in der Wüste herrscht.", completion = "Oh ja, das sieht gut aus. Ich werde alles hübsch verpacken, damit nichts verloren geht. Habt vielen Dank für Eure Hilfe. In meinen Augen seid Ihr die absolute Nummer eins, wenn es um das Angeln von Tüpfelgelbschwänzen geht! Tja, und falls Ihr noch mehr angelt und kocht, scheut Euch nicht, sie mir zu bringen. Ich werde dann sicherstellen, dass jeder von Eurer Spende erfährt." }, enUS = { progress = "Back so soon with the spotted yellowtail, {class}? You rememba' to cook it up nice? We not servin' raw fish to the soldiers out in the hot desert sun, to be sure.", completion = "Oh ya, this be the good stuff. I pack it up real nice so it not go to waste. Thanks be to you for helpin' me out like this. I'm thinkin' you an A-number-one fisherman for all this spotted yellowtail. An if you happen to fish up and cook even more, you bring it to me here; I make sure everyone know you did!" } })
apply(8622, { "classic", "forever" }, { deDE = { progress = "Der furchtbare C'Thun wartet ruhend in seiner Behausung in Ahn'Qiraj.", completion = "Ich habe nicht erwartet, dass Ihr von Eurer Unternehmung zurückkehrt, {name}.\n\nIhr habt eine größere Vorsehung erfüllt als die der meisten sterblichen Wesen.\n\nIndem Ihr C'Thun bezwungen habt, habt Ihr nicht nur ganz Azeroth gerettet, sondern auch kosmische Ereignisse in Gang gesetzt, die weit über Eurem Vorstellungsvermögen liegen.\n\nNehmt diese Brustplatte als Zeichen des Ruhms und der Bürde an, die Euch in Folge Eurer Taten erwarten werden.\n\nMöge ihre Macht bei Euren zukünftigen Herausforderungen mit Euch sein, Göttertöter!" }, enUS = { progress = "At his dwelling in Ahn'Qiraj, dread C'Thun awaits in slumber.", completion = "I did not expect you to return from your attempt, {name}.\n\nYou've fulfilled a destiny greater than that of most immortal beings.\n\nBy slaying C'Thun you've not only saved all of Azeroth, you've also tipped the scales of cosmic events beyond your comprehension.\n\nAccept this breastplate as a symbol of the glory and burden that will come as a consequence of your actions.\n\nMay its power aid you in the challenges that await you, god-slayer!" } })
apply(8623, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, {name}?", completion = "Ihr seid erfolgreich gewesen! Das Flüstern der Zwillingsimperatoren ist verstummt.\n\nNehmt dies als Belohnung. Der bloße Anblick hiervon wird Furcht in die Herzen der Qiraji treiben... es soll sie an ihre gefallenen Anführer erinnern und an den Sterblichen, der sie niederstreckte." }, enUS = { progress = "Did you bring me the components I asked for, {name}?", completion = "You've succeeded!  The whispers from the Twin Emperors have ceased.\n\nTake this as a reward.  The mere sight of it will strike fear in the hearts of the Qiraji... it shall remind them of their fallen leaders and of the mortal that slew them." } })
apply(8632, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, {name}?", completion = "Ihr seid erfolgreich gewesen! Das Flüstern der Zwillingsimperatoren ist verstummt.\n\nNehmt dies als Belohnung. Der bloße Anblick hiervon wird Furcht in die Herzen der Qiraji treiben... es soll sie an ihre gefallenen Anführer erinnern und an den Sterblichen, der sie niederstreckte." }, enUS = { progress = "Did you bring me the components I asked for, {name}?", completion = "You've succeeded!  The whispers from the Twin Emperors have ceased.\n\nTake this as a reward.  The mere sight of it will strike fear in the hearts of the Qiraji... it shall remind them of their fallen leaders and of the mortal that slew them." } })
