apply(8687, { "classic", "forever" }, { deDE = { progress = "Ihr habt etwas, das Ihr mir erzählen wollt, {class}?", completion = "Ausgezeichnete Arbeit, {name}. Die Silithiden werden ohne ihre Tunnelgräber Schwierigkeiten haben, all die Schäden zu reparieren, die ihre Baustruktur erlitten hat. Ich vermute, dass Ihr nach einer neuen Aufgabe sucht." }, enUS = { progress = "You have something to tell me, {class}?", completion = "Excellent work, {name}.  Without their tunnelers, the silithid will have a hard time repairing any damage inflicted to their hive's structure.  I assume you'll want a new task." } })
apply(8705, { "classic", "forever" }, { deDE = { progress = "Habt Ihr mir die benötigten Bestandteile gebracht, {name}?", completion = "Das habt Ihr gut gemacht, {class}. Dies ist ein Meisterstück... die Balance ist perfekt.\n\nNehmt Eure Waffe, {name}. Schwingt sie zuversichtlich und vernichtet unsere Feinde!" }, enUS = { progress = "Did you bring me the components I require, {name}?", completion = "You've done well, {class}.  This is a masterwork hilt... the balance is perfect.\n\nTake your weapon, {name}.  Wield it with great confidence and vanquish our enemies!" } })
apply(8709, { "classic", "forever" }, { deDE = { progress = "Habt Ihr mir die benötigten Bestandteile gebracht, {name}?", completion = "Das habt Ihr gut gemacht, {class}. Dies ist ein Meisterstück... die Balance ist perfekt.\n\nNehmt Eure Waffe, {name}. Schwingt sie zuversichtlich und vernichtet unsere Feinde!" }, enUS = { progress = "Did you bring me the components I require, {name}?", completion = "You've done well, {class}.  This is a masterwork hilt... the balance is perfect.\n\nTake your weapon, {name}.  Wield it with great confidence and vanquish our enemies!" } })
