apply(8741, { "classic", "forever" }, { deDE = { progress = "<Anachronos nickt.>", completion = "Jeder wird von Euren Taten erfahren, Held. Man wird Loblieder von Orgrimmar bis weit in den südlichen Meeren singen. Jeder wird den Held des Bronzeschwarms kennen, {name}." }, enUS = { progress = "<Anachronos nods.>", completion = "Your deeds will be known to all, champion. They will sing your praises from Orgrimmar to the far reaches of the South Seas. All will know of the champion of the Bronze Flight, {name}." } })
apply(8763, { "classic", "forever" }, { deDE = { progress = "Der Tannenzweigkonservierer sieht auf den ersten Blick wie eine Art Destillierapparat aus, bei genauerer Betrachtung werden allerdings einige goblinartige Veränderungen offensichtlich. Eure Fähigkeiten in der Kochkunst erlauben es Euch allerdings zu verstehen, wie die Maschine funktioniert.\n\nEs sind schon frische Tannenzweige in der Maschine - Ihr müsst nur noch Tiefsteinsalz dazugeben und fünf Goldstücke einwerfen, um sie ans Laufen zu bringen.", completion = "Die Maschine fängt an zu rumpeln und Dampf auszuspeien, während sie mit der Arbeit beginnt. Schon kurz darauf ist sie fertig. Sie spuckt noch etwas Dampf aus und eine Klappe öffnet sich. In der Öffnung befindet sich ein Bündel konservierter Tannenzweige." }, enUS = { progress = "The \"Holly Preserver\" machine looks like some sort of still at first, but a careful examination of it reveals some goblin-esque changes to it.  Still, your skill at cooking seems to allow you to understand how the machine works.\n\nThere is already fresh holly in the machine - you simply need to provide some deeprock salt and five gold coins to get the machine working.", completion = "The machine lets off a little rumble and a small amount of steam as it starts working.  It is not too long thereafter until it stops, heralded by another small jet of steam erupting from it.  A door hatch opens, revealing a batch of preserved holly!" } })
apply(8770, { "classic", "forever" }, { deDE = { progress = "Ihr habt etwas, das Ihr mir erzählen wollt, {class}?", completion = "Ausgezeichnete Arbeit, {name}. Euer Eifer ist bemerkenswert!" }, enUS = { progress = "You have something to tell me, {class}?", completion = "Excellent work, {name}.  Your diligence is as noteworthy as always." } })
apply(8771, { "classic", "forever" }, { deDE = { progress = "Ihr habt etwas, das Ihr mir erzählen wollt, {class}?", completion = "Exzellente Arbeit, {name}. Eure Leistungen beim Angriff auf den Bau des Ashischwarms wurden zur Kenntnis genommen." }, enUS = { progress = "You have something to tell me, {class}?", completion = "Excellent work, {name}.  Your part in the attack on Hive'Ashi has been noted." } })
apply(8772, { "classic", "forever" }, { deDE = { progress = "Ihr habt etwas, das Ihr mir erzählen wollt, {class}?", completion = "Exzellente Arbeit, {name}. Eure Leistungen beim Angriff auf den Bau des Zoraschwarms wurden zur Kenntnis genommen." }, enUS = { progress = "You have something to tell me, {class}?", completion = "Excellent work, {name}.  Your part in the attack on Hive'Zora has been noted." } })
apply(8773, { "classic", "forever" }, { deDE = { progress = "Ihr habt etwas, das Ihr mir erzählen wollt, {class}?", completion = "Ausgezeichnete Arbeit, {name}. Ich habe nur Gutes über Eure Teilnahme an dem Angriff gegen den Zoraschwarm gehört. Macht so weiter und der Sieg wird schon bald unser sein." }, enUS = { progress = "You have something to tell me, {class}?", completion = "I've heard good things about your part in the Hive'Zora attack.  Keep up the good work and victory will soon be ours." } })
apply(8775, { "classic", "forever" }, { deDE = { progress = "Ihr wollt mir etwas mitteilen, {name}?", completion = "Exzellente Arbeit, {name}. Eure Leistungen beim Angriff auf den Bau des Regalschwarms wurden zur Kenntnis genommen." }, enUS = { progress = "You wish to tell me something, {name}?", completion = "Excellent work, {name}.  Your part in the attack on Hive'Regal has been noted." } })
apply(8777, { "classic", "forever" }, { deDE = { progress = "Ihr wollt mir etwas mitteilen, {name}?", completion = "Exzellente Arbeit, {name}. Eure Leistungen beim Angriff auf den Bau des Regalschwarms wurden zur Kenntnis genommen." }, enUS = { progress = "You wish to tell me something, {name}?", completion = "Excellent work, {name}.  Your part in the attack on Hive'Regal has been noted." } })
apply(8783, { "classic", "forever" }, { deDE = { progress = "Ihr habt etwas für mich, {name}?", completion = "Ah, sehr gut. Dieses Material ist von hervorragender Qualität. Vielen Dank, {name}." }, enUS = { progress = "You have something for me, {name}?", completion = "Ah, yes.  These materials are of excellent quality.  Thank you, {name}." } })
apply(8784, { "classic", "forever" }, { deDE = { progress = "Ihr glüht! Ich weiß, was das bedeutet…", completion = "Ein einmaliger Fund, {name}. Einfach fantastisch! Mit Hilfe dieses Artefakts, erhalten wir sicherlich einen Einblick in die verquerte Denkensweise des Feindes." }, enUS = { progress = "You're glowing! I know what that means...", completion = "An exceptional find, {name}. Simply marvelous! This will definitely give us some insight into our enemy's twisted minds." } })
apply(8785, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Materialien, {name}?", completion = "Ah, sehr gut. Genau, was ich gebraucht habe. Aus diesen Zutaten werde ich ein ganz spezielles Gebräu mischen. Den Silithiden wird es bestimmt nicht gut bekommen!" }, enUS = { progress = "Do you have my materials, {name}?", completion = "Ah, yes.  Just what I needed!  I'll make a special concoction with this.  The silithid won't like it one bit!" } })
apply(8791, { "classic", "forever" }, { deDE = { progress = "Ah, {name}. Wie ich sehe, seid Ihr zurückgekehrt und sogar in einem Stück! Welche Neuigkeiten bringt Ihr aus Ahn'Qiraj?", completion = "Ich entbiete Euch meine höchste Anerkennung und erlaube es Euch, einen Gegenstand von höchster Macht auszuwählen, {name}! Ihr habt den Bewohnern von Kalimdor einen großen Dienst erwiesen." }, enUS = { progress = "Ah, {name}, you have returned! And in one piece, I might add. What news do you bring from Ahn'Qiraj?", completion = "I offer you my highest commendation and your choice of an item of power, {name}. You have done the people of Kalimdor a great service." } })
apply(8792, { "classic", "forever" }, { deDE = { completion = "Throm'ka, {class}! Es ist schön zu sehen, dass Ihr uns in dieser dunklen Stunde zur Seite steht, {name}! So viele Mitglieder der Horde haben sich bereits freiwillig verpflichtet, uns bei den Vorbereitungen für den aufziehenden Krieg in Ahn'Qiraj zu unterstützen. Unsere Anstrengungen hier, werden der Garant für den Sieg über die Silithiden und Ihre dunklen Meister sein!\n\nNun, jetzt da Ihr hier seid, solltet Ihr Euch mit den örtlichen Sammlern unterhalten und sehen, welche Materialien Ihr am besten beschaffen könnt." }, enUS = { completion = "Throm'ka, {class}! Good to see so many of the Horde, such as yourself, {name}, coming out to lend your support in laying the groundwork for the upcoming Ahn'Qiraj War. The effort here will ensure that we are victorious against the Silithid and their evil masters hidden away inside Ahn'Qiraj.\n\nSo now that you are here, be sure to speak with the various collectors and offer your assistance in gathering those materials that you are suited to." } })
