apply(8796, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, {class}! Es ist schön zu sehen, dass Ihr uns in dieser dunklen Stunde zur Seite steht, {name}! So viele Mitglieder der Allianz haben sich bereits freiwillig verpflichtet, uns bei den Vorbereitungen für den aufziehenden Krieg in Ahn'Qiraj zu unterstützen. Unsere Anstrengungen hier, werden der Garant für den Sieg über die Silithiden und Ihre dunklen Meister sein!\n\nNun, jetzt da Ihr hier seid, solltet Ihr Euch mit den örtlichen Sammlern unterhalten und sehen, welche Materialien Ihr am besten beschaffen könnt." }, enUS = { completion = "Hail and well met lad! Good to see so many of the Alliance, such as yourself, {name}, coming out to lend your support in laying the groundwork for the upcoming Ahn'Qiraj War. The effort here will ensure that we are victorious against the Silithid and their evil masters hidden away inside Ahn'Qiraj.\n\nSo now that you are here, be sure to speak with the various collectors and offer your assistance in gathering those materials that you are suited to." } })
apply(8797, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, {class}! Es ist schön zu sehen, dass Ihr uns in dieser dunklen Stunde zur Seite steht, {name}! So viele Mitglieder der Allianz haben sich bereits freiwillig verpflichtet, uns bei den Vorbereitungen für den aufziehenden Krieg in Ahn'Qiraj zu unterstützen. Unsere Anstrengungen hier, werden der Garant für den Sieg über die Silithiden und Ihre dunklen Meister sein!\n\nNun, jetzt da Ihr hier seid, solltet Ihr Euch mit den örtlichen Sammlern unterhalten und sehen, welche Materialien Ihr am besten beschaffen könnt." }, enUS = { completion = "Hail and well met lad! Good to see so many of the Alliance, such as yourself, {name}, coming out to lend your support in laying the groundwork for the upcoming Ahn'Qiraj War. The effort here will ensure that we are victorious against the Silithid and their evil masters hidden away inside Ahn'Qiraj.\n\nSo now that you are here, be sure to speak with the various collectors and offer your assistance in gathering those materials that you are suited to." } })
apply(8799, { "classic", "forever" }, { deDE = { progress = "Der Tannenzweigkonservierer sieht auf den ersten Blick wie eine Art Destillierapparat aus, bei genauerer Betrachtung werden allerdings einige goblinartige Veränderungen offensichtlich. Eure Fähigkeiten in der Kochkunst erlauben es Euch allerdings zu verstehen, wie die Maschine funktioniert.\n\nEs sind schon frische Tannenzweige in der Maschine - Ihr müsst nur noch Tiefsteinsalz dazugeben und fünf Goldstücke einwerfen, um sie ans Laufen zu bringen.", completion = "Die Maschine fängt an zu rumpeln und Dampf auszuspeien, während sie mit der Arbeit beginnt. Schon kurz darauf ist sie fertig. Sie spuckt noch etwas Dampf aus und eine Klappe öffnet sich. In der Öffnung befindet sich ein Bündel konservierter Tannenzweige." }, enUS = { progress = "The \"Holly Preserver\" machine looks like some sort of still at first, but a careful examination of it reveals some goblin-esque changes to it.  Still, your skill at cooking seems to allow you to understand how the machine works.\n\nThere is already fresh holly in the machine - you simply need to provide some deeprock salt and five gold coins to get the machine working.", completion = "The machine lets off a little rumble and a small amount of steam as it starts working.  It is not too long thereafter until it stops, heralded by another small jet of steam erupting from it.  A door hatch opens, revealing a batch of preserved holly!" } })
apply(8800, { "classic", "forever" }, { deDE = { completion = "Kaldon schickt Euch? Nun gut, lasst uns sehen, was ich für Euch tun kann." }, enUS = { completion = "Kaldon sent you?  Very well, let's see what we can do for you." } })
apply(8804, { "classic", "forever" }, { deDE = { progress = "Ihr habt etwas für mich?", completion = "Ausgezeichnet. Diese Pakete haben wir wirklich dringend benötigt, {name}. Gute Arbeit." }, enUS = { progress = "You have something for me?", completion = "Excellent!  We were in need of these, {name}.  Thanks." } })
apply(8809, { "classic", "forever" }, { deDE = { progress = "Ihr habt etwas für mich, {name}?", completion = "Ah, sehr gut. Dieses Material ist von hervorragender Qualität. Vielen Dank, {name}." }, enUS = { progress = "You have something for me, {name}?", completion = "Ah, yes.  These materials are of excellent quality.  Thank you, {name}." } })
apply(8828, { "classic", "forever" }, { deDE = { completion = "Ho, ho, hallo! Ihr seid aus einem ganz bestimmten Grund hier, richtig? Ihr wollt Eure Winterhauchgeschenke endlich öffnen.\n\nNun, macht Euch mal keine Sorgen! Altvater Winter würde doch niemals seinen Liebsten vergessen. Schaut einfach unter dem Baum nach, dort findet Ihr Eure Geschenke.\n\nUnd da dies eine Zeit des Gebens ist: Meint Ihr nicht, dass Eure Freunde sich über einige der fantastischen Produkte von Kokelwälder freuen würden?" }, enUS = { completion = "Oh, ho hello there! You can only be here for one reason: to open your Winter Veil presents.\n\nNow, don't you worry, Great-father Winter hasn't forgotten about his favorite {race} {class}. Look under the tree and you'll find your gifts.\n\nDuring this season of giving, perhaps your friends would also enjoy receiving some of Smokeywood Pasture's excellent products?" } })
apply(8856, { "classic", "forever" }, { deDE = { description = "Seitdem ständig neue Rekruten auf Burg Cenarius eintreffen, stehen wir vor dem Problem, sie in der Wüste am Leben zu erhalten. Der ständige Wasserentzug und die zahlreichen giftigen Kreaturen in dieser Gegend sind eine ernstzunehmende Gefahr für die unerfahren Soldaten. Sammelt alles, was notwendig ist, um ein Wüstenüberlebenspaket zusammenzustellen und bringt die erforderlichen Vorräte zu Calandrath auf Burg Cenarius.", objectives = "Bringt 4 Kugeln des Wassers, 4 mächtige Gegengifte und 4 gebackene Lachse zu Calandrath in der Taverne von Burg Cenarius in Silithus." } })
apply(8861, { "classic", "forever" }, { deDE = { progress = "Guten Tag, {class}! Seid Ihr wegen den Feierlichkeiten nach Thunder Bluff gekommen? Oder wollt Ihr nur ein wenig Eure von der Jagd müden Hufe ausruhen?", completion = "Oh, sehr gut! Mit diesen Vorräten sollte ich alle Feiernden auf dem Neujahrsfest bewirten können!\n\nIch danke Euch, {name}. Ich stehe in Eurer Schuld. Bitte, nehmt diese Münzen als Dankeschön... und befolgt meinen Rat - nehmt einen herzhaften Schluck aus dem Fass draußen und schließt Euch den anderen beim Feiern des neuen Jahres an!" }, enUS = { progress = "Good day, {class}!  Did you come to Thunder Bluff for our celebrations?  Or are you here to rest a weary hoof between hunts?", completion = "Oh, very good!  These supplies will help feed all our people, here to celebrate the new year!\n\nI thank you, {name}.  You are in my debt.  Please, take these coins... and heed my advice - drink heartily from the kegs outside, and join our revelers in a dance of celebration!" } })
apply(8867, { "classic", "forever" }, { deDE = { progress = "Konntet Ihr die Zünder finden, {name}?", completion = "Gut gemacht, {name}.\n\nDa Ihr jetzt in der richtigen Stimmung seid, nehmt doch diese Einladung zu dem Fest in Moonglade an.\n\nEs sind recht unterhaltsame Feierlichkeiten, falls Ihr etwas Zeit haben solltet. Wir teilen dort miteinander gutes Essen, Getränke, Geschichten und natürlich... noch mehr Feuerwerk!\n\nÖffnet die Einladung, während Ihr innerhalb des Mondlichtkreises steht und Ihr werdet nach Moonglade transportiert." }, enUS = { progress = "Did you find the launchers, {name}?", completion = "Well done, {name}.\n\nNow that you're in the spirit of things, why don't you take this invitation to the festival in Moonglade.\n\nIt's quite an enjoyable celebration, if you have the time to spare.  We share food, drink, stories and of course... more fireworks!\n\nOpen the invitation while standing inside the circle of greater moonlight and you'll be transported to Moonglade." } })
apply(8869, { "classic", "forever" }, { deDE = { description = "In den Grenzen der Scharlachroten Bastion liegt die süße Beschaulichkeit. Der purpurrote Hammerschmied bewacht das Rezept mit seinem Leben. Besiegt ihn und bringt mir seine Schürze. Dafür werde ich Euch zu einem Hammerschmied ausbilden.\n\nIhr müsst eines wissen: Wenn Ihr Euch für den Weg des Hammerschmieds entschieden habt, sind die Wege des Schwertschmieds und des Axtschmieds nicht mehr verfügbar.", objectives = "Begebt Euch nach Stratholme und tötet den purpurroten Hammerschmied. Nehmt die Schürze des purpurroten Hammerschmiedes und kehrt zu Lilith zurück." } })
apply(8873, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?" }, enUS = { completion = "Welcome, {name}.  Are you here to join in the festivities?" } })
apply(8874, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?" }, enUS = { completion = "Welcome, {name}.  Are you here to join in the festivities?" } })
apply(8875, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?" }, enUS = { completion = "Welcome, {name}.  Are you here to join in the festivities?" } })
apply(8900, { "classic", "forever" }, { deDE = { progress = "Oh, und welchen Umständen verdanke ich dieses Vergnügen?", completion = "Man mag es kaum glauben, dass ein Orc derart wortgewandt sein kann. Natürlich hatten wir bisher kaum Chancen, die Orcs im Allgemeinen besser kennenzulernen. Vielen Dank, für das Überbringen dieses Briefs." }, enUS = { progress = "Oh, and to what do I owe this pleasure?", completion = "You wouldn't expect an orc to be so eloquent. Of course, we never really had a chance to know them before now. Thank you for bringing this to me." } })
apply(8902, { "classic", "forever" }, { deDE = { progress = "Oh, und welchen Umständen verdanke ich dieses Vergnügen?", completion = "Dieser Brief weckt Erinnerungen an ein längst vergangenes Leben, {name}. Elenia Tor. Einst war dies mein Name, wisst Ihr. Eine wundervolle Zeremonie an den Ufern des Sees sollte es werden. Er wollte sich zur Ruhe setzen und gemeinsam wollten wir uns auf einem Bauernhof niederlassen.\n\nEs waren einfache Träume, die wir hatten.\n\nDoch wenn er mich nun sehen könnte, ich glaube kaum, dass er die alte Elenia in mir wiedererkennen würde. Nur kaltes Fleisch und ein totes Herz..." }, enUS = { progress = "Oh, and to what do I owe this pleasure?", completion = "This brings back memories from a lifetime ago, {name}. Elenia Tor. That was going to be my name, you know. We would have a beautiful ceremony out on the shores of the lake. When he retired, we'd find a farm to retire to.\n\nSimple dreams, then.\n\nBut if he saw me now, I doubt he'd even see Elenia in me. Only cold flesh and a dead heart..." } })
apply(8904, { "classic", "forever" }, { deDE = { progress = "Waren meine Sorgen berechtigt? Wurden unsere idiotischen Wachen überwältigt?", completion = "Es ist also wahr! Das ist unglaublich, wie konnte das nur passieren? Lasst mich einen Moment nachdenken. Es muss doch eine Ursache für all das geben." }, enUS = { progress = "Was I right to worry? Have our idiot guardians been overcome?", completion = "So it is true. This is unbelievable. How could this have happened? Let me think for a moment. There must be a reason behind this." } })
apply(8915, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die von mir benötigten Gegenstände beisammen, {name}?", completion = "Ja, Mux sollte damit hochzufrieden sein.\n\nDiese Armschienen sind ein Teil eines vollständigen Rüstungssets. Solltet Ihr gewillt sein, mich weiterhin zu unterstützen, würde ich es in Betracht ziehen, mich auch von den anderen Teilen zu trennen." }, enUS = { progress = "Have you obtained the items I require, {name}?", completion = "Ah, yes.  Mux will be quite happy with this.\n\nThose bracers were part of a larger armor set.  If you're interested in providing me with further assistance,  I'd be willing to consider parting with the rest of it." } })
apply(8917, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die von mir benötigten Gegenstände beisammen, {name}?", completion = "Ja, Mux sollte damit hochzufrieden sein.\n\nDiese Armschienen sind ein Teil eines vollständigen Rüstungssets. Solltet Ihr gewillt sein, mich weiterhin zu unterstützen, würde ich es in Betracht ziehen, mich auch von den anderen Teilen zu trennen." }, enUS = { progress = "Have you obtained the items I require, {name}?", completion = "Ah, yes.  Mux will be quite happy with this.\n\nThose bracers were part of a larger armor set.  If you're interested in providing me with further assistance,  I'd be willing to consider parting with the rest of it." } })
apply(8920, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die von mir benötigten Gegenstände beisammen, {name}?", completion = "Ja, Mux sollte damit hochzufrieden sein.\n\nDiese Armschienen sind ein Teil eines vollständigen Rüstungssets. Solltet Ihr gewillt sein, mich weiterhin zu unterstützen, würde ich es in Betracht ziehen, mich auch von den anderen Teilen zu trennen." }, enUS = { progress = "Have you obtained the items I require, {name}?", completion = "Ah, yes.  Mux will be quite happy with this.\n\nThose bracers were part of a larger armor set.  If you're interested in providing me with further assistance,  I'd be willing to consider parting with the rest of it." } })
apply(8939, { "classic", "forever" }, { deDE = { progress = "Seid Ihr bereit, den Austausch vorzunehmen?", completion = "Unsere Vereinbarung steht. Denkt nur daran, dass dies nur ein Vorgeschmack dessen ist, was Euch erwartet. Befreit mich von diesem verfluchten Schicksal und ich werde Euch mit Gegenständen von wahrer Macht belohnen." }, enUS = { progress = "You're ready to perform the exchange?", completion = "Our agreement remains in place.  Just remember, this is but a taste of what awaits you.  Free me of this cursed fate and I will reward you with items of truly great power." } })
apply(8941, { "classic", "forever" }, { deDE = { progress = "Seid Ihr bereit, den Austausch vorzunehmen?", completion = "Unsere Vereinbarung steht. Denkt nur daran, dass dies nur ein Vorgeschmack dessen ist, was Euch erwartet. Befreit mich von diesem verfluchten Schicksal und ich werde Euch mit Gegenständen von wahrer Macht belohnen." }, enUS = { progress = "You're ready to perform the exchange?", completion = "Our agreement remains in place.  Just remember, this is but a taste of what awaits you.  Free me of this cursed fate and I will reward you with items of truly great power." } })
apply(8946, { "classic", "forever" }, { deDE = { progress = "Ysida... Ist sie am Leben?", completion = "Dieses Medaillon... Ihr habt sie gefunden! Jetzt kann ich endlich in Frieden ruhen.\n\nIch werde nun all Eure Fragen beantworten, {name}. Aber stellt sie schnell, meine Zeit in dieser Welt läuft ab." }, enUS = { progress = "Ysida... is she alive?", completion = "That locket... you found her!  I can rest in peace at long last.\n\nI shall now answer any questions you might have, {name}.  But make haste, my time in this world is not long." } })
apply(8978, { "classic", "forever" }, { deDE = { progress = "Ihr habt den Apparat?", completion = "Ihr seid mit dem Apparat zurückgekehrt! Eure Hingabe beeindruckt mich, {name}. Ausgezeichnete Arbeit." }, enUS = { progress = "You've returned with the device?", completion = "You've returned with the device!  I'm impressed by your dedication, {name}.  Excellent work." } })
apply(9002, { "classic", "forever" }, { deDE = { progress = "Seid Ihr bereit, mir unserer Abmachung entsprechend Eure Teile der Lichtrüstung im Austausch gegen den neuen Helm der Seelenschmiede und die neue Brustplatte der Seelenschmiede zu geben?", completion = "Ich werde Euch wahrlich vermissen, {name}. Ich stehe tief in Eurer Schuld, eine Schuld, die ich vermutlich niemals in der Lage sein werde zu begleichen.\n\nGenießt Eure neue Rüstung. Möge sie Euch für lange Zeit beschützen." }, enUS = { progress = "As per our deal, are you ready to hand over your Lightforge pieces in exchange for your new Soulforge Helm and Breastplate?", completion = "I'm going to miss you, {name}. I owe you such a debt of gratitude; I think I'll never be able to repay it.\n\nI hope that you enjoy your new head and chest armor, and that it protects you for a long time to come." } })
apply(9040, { "classic", "forever" }, { deDE = { progress = "Diese Stulpen sind für das Tragen einer edlen Waffe geschaffen.", completion = "Möge sich Euer Griff um den Hals Kel'Thuzads festigen.\n\n<Korfax macht eine reißende Bewegung mit seinen Händen.>" }, enUS = { progress = "These gauntlets are made to grip a fine weapon.", completion = "May your grip tighten around the neck of Kel'Thuzad.\n\n<Korfax makes a wrenching motion with his hands.>" } })
apply(9041, { "classic", "forever" }, { deDE = { progress = "Der Gürtel steht für Modebewusstsein und schützende Ausrüstung zugleich.", completion = "Verwendet ihn als Schlinge für Eure Gegner... und tragt ihn gut sichtbar beim Besuch Eurer Goblindisko. Ihr werdet das Tagesgespräch der Stadt sein!" }, enUS = { progress = "The belt is both a fashion statement and a powerful piece of protective gear.", completion = "Use it as a noose for your enemies. Also, wear it out to your local goblin disco. You will be the talk of the town!" } })
apply(9042, { "classic", "forever" }, { deDE = { progress = "Die Handgelenke sind die zweitverletzlichste Stelle des Körpers... oder ist es die vierte?", completion = "Denkt daran, die Handgelenke sind die fünftverletzlichste Stelle des Körpers! Schützt Eure Handgelenke und sie werden ganz sicher Eure Ellbogen schützen - vielleicht." }, enUS = { progress = "The wrist is the second most vulnerable spot on a body... Or is it the fourth?", completion = "Remember, the wrist is the fifth most vulnerable spot on a body! Protect your wrists and they'll definitely protect your elbows - maybe." } })
apply(9103, { "classic", "forever" }, { deDE = { progress = "Der verlorene Hamster kehrt zurück! Habt Ihr die von mir benötigten Dinge?", completion = "Seht Ihr? Versteht Ihr jetzt die Macht? Läuterung... welch' Narren...\n\n<Mataus schüttelt missbilligend seinen Kopf.>\n\nNehmt jetzt Euer Zeug und geht mir aus den Augen." }, enUS = { progress = "The prodigal rodent returns! Have you what I require?", completion = "Do you see? Do you now understand the power? Purification... What fools...\n\n<Mataus shakes his head disapprovingly.>\n\nNow take it and get out of my sight." } })
apply(9106, { "classic", "forever" }, { deDE = { progress = "Der verlorene Hamster kehrt zurück! Habt Ihr die von mir benötigten Dinge?", completion = "Seht Ihr? Versteht Ihr jetzt die Macht? Läuterung... welch' Narren...\n\n<Mataus schüttelt missbilligend seinen Kopf.>\n\nNehmt jetzt Euer Zeug und geht mir aus den Augen." }, enUS = { progress = "The prodigal rodent returns! Have you what I require?", completion = "Do you see? Do you now understand the power? Purification... What fools...\n\n<Mataus shakes his head disapprovingly.>\n\nNow take it and get out of my sight." } })
apply(9107, { "classic", "forever" }, { deDE = { progress = "Der verlorene Hamster kehrt zurück! Habt Ihr die von mir benötigten Dinge?", completion = "Seht Ihr? Versteht Ihr jetzt die Macht? Läuterung... welch' Narren...\n\n<Mataus schüttelt missbilligend seinen Kopf.>\n\nNehmt jetzt Euer Zeug und geht mir aus den Augen." }, enUS = { progress = "The prodigal rodent returns! Have you what I require?", completion = "Do you see? Do you now understand the power? Purification... What fools...\n\n<Mataus shakes his head disapprovingly.>\n\nNow take it and get out of my sight." } })
apply(9108, { "classic", "forever" }, { deDE = { progress = "Der verlorene Hamster kehrt zurück! Habt Ihr die von mir benötigten Dinge?", completion = "Seht Ihr? Versteht Ihr jetzt die Macht? Läuterung... welch' Narren...\n\n<Mataus schüttelt missbilligend seinen Kopf.>\n\nNehmt jetzt Euer Zeug und geht mir aus den Augen." }, enUS = { progress = "The prodigal rodent returns! Have you what I require?", completion = "Do you see? Do you now understand the power? Purification... What fools...\n\n<Mataus shakes his head disapprovingly.>\n\nNow take it and get out of my sight." } })
apply(9109, { "classic", "forever" }, { deDE = { progress = "Der verlorene Hamster kehrt zurück! Habt Ihr die von mir benötigten Dinge?", completion = "Seht Ihr? Versteht Ihr jetzt die Macht? Läuterung... welch' Narren...\n\n<Mataus schüttelt missbilligend seinen Kopf.>\n\nNehmt jetzt Euer Zeug und geht mir aus den Augen." }, enUS = { progress = "The prodigal rodent returns! Have you what I require?", completion = "Do you see? Do you now understand the power? Purification... What fools...\n\n<Mataus shakes his head disapprovingly.>\n\nNow take it and get out of my sight." } })
apply(9120, { "classic", "forever" }, { deDE = { progress = "HEILIGES LICHT! Was ist denn in Euch gefahren, Junge?", completion = "Ich hätte mir nie erträumt, dass ich das eines Tages mal zu Gesicht bekommen sollte...\n\n<Vater Montoy scheint lüstern zu geifern.>\n\nOh ja, Ihr sollt entlohnt werden, mein Junge. Reichlich entlohnt. Gebt es mir. Jetzt!" }, enUS = { progress = "BLESSED LIGHT! What foulness do you hold, boy?", completion = "In all my days of living I would have never expected to see this...\n\n<Father Montoy appears to be salivating.>\n\nOh yes, you will be rewarded dear boy. You will be greatly rewarded. Give it here. Now!" } })
apply(9121, { "classic", "forever" }, { deDE = { progress = "Keiner von denen, die Naxxramas betreten haben, hat überlebt, um davon berichten zu können.", completion = "Ihr werdet ein leichtes Prickeln verspüren, {name}. Dieses Gefühl ist das Zeichen dafür, dass es funktioniert. Sobald das Ganze abgeschlossen ist, werdet Ihr Naxxramas durch das Runenportal im Pestwald betreten können." }, enUS = { progress = "None have entered Naxxramas and lived to tell the tale.", completion = "You will feel a slight tingle, {name}. That sensation means it's working. Once complete, you will be able to enter Naxxramas by stepping upon the rune portal in Plaguewood." } })
apply(9124, { "classic", "forever" }, { deDE = { progress = "Wie geht es mit der Jagd voran?", completion = "Ah, die werden sich gut eignen, {name}. Vergesst nicht, ich nehme jederzeit noch mehr Teile entgegen. Für jede Ladung, die Ihr mir bringt, belohne ich Euch mit einer Insignie." }, enUS = { progress = "How goes the hunt?", completion = "Ah, that'll do nicely, {name}. Remember, I'm always accepting more parts. For every bundle you bring me, I'll reward you with an insignia." } })
apply(9126, { "classic", "forever" }, { deDE = { progress = "Ich kann Euch die Richtung zu Orten weisen, die von Skeletten heimgesucht werden, {class}.", completion = "Ihr seid schnell, {name}. Schnell wie der Wind... Sagt mal, habe ich Euch schon von meiner Zeit in dem Barbershop-Quartett erzählt?\n\nErinnert mich das nächste Mal daran, Euch davon zu berichten." }, enUS = { progress = "I can direct you to skeleton infested locales, {class}.", completion = "You work fast, {name}. Fast like a fox... Say, have I ever told you about the time I was in a barber shop quartet?\n\nRemind me to tell you that story one of these days." } })
apply(9128, { "classic", "forever" }, { deDE = { progress = "Ich kann Euch lediglich die Richtung weisen, {name}.", completion = "Ausgezeichnete Arbeit, {name}! Hier, wie versprochen Eure Insignie. Vergesst nicht, wo das hier herkommt, gibt es noch mehr..." }, enUS = { progress = "I can only steer you in the right direction, {name}.", completion = "A job well done, {name}! As promised, the insignia is yours. Just remember, there's more where that came from..." } })
apply(9136, { "classic", "forever" }, { deDE = { progress = "Ich bin mit dem Pflanzenreich unserer Welt sehr vertraut. Braucht Ihr Richtungsangaben?", completion = "Ich bin Euch sehr verbunden, {name}.\n\n\n\nBitte denkt daran, dass ich jederzeit Wedel entgegennehme." }, enUS = { progress = "I have intimate knowledge of the flora in our world. Do you require direction?", completion = "I am much obliged, {name}.\n\n\n\nPlease remember that I am always accepting fronds." } })
apply(9141, { "classic", "forever" }, { deDE = { progress = "<Einsatzkommandant Metz kaut auf seiner Zigarre.>\n\nWas gibt's? Ich bin ein vielbeschäftigter Mann.", completion = "In Ordnung, so funktioniert's: Für jede Ehrenmarke, die Ihr abgebt, gebe ich Euch eine Verfügung. Ihr führt die Anweisung auf dieser Verfügung aus und liefert die Waren an Rottenkommandant Stonebruiser. Kapiert? Dann raus mit Euch." }, enUS = { progress = "<Commander Metz chews on his cigar.>\n\nWhat is it? I'm a busy man.", completion = "Alright, here's how it works: For every valor token that you turn in, I'll give you another writ. You complete the order on that writ and deliver the order to Packmaster Stonebruiser. Got it? Good. Now get out of here." } })
apply(9178, { "classic", "forever" }, { deDE = { progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Jawohl, die werden sich für die schonungslosen Waffen der Infanterie noch als nützlich erweisen." }, enUS = { progress = "Filling a work order, {class}?", completion = "Yep, these will come in handy for the infantry's bashin' weapons." } })
apply(9182, { "classic", "forever" }, { deDE = { progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Die sind nicht halb so groß, wie ich es erwartet habe. Wie auch immer, Geschäft ist Geschäft." }, enUS = { progress = "Filling a work order, {class}?", completion = "These aren't as huge as I expected. Regardless, a deal is a deal." } })
apply(9183, { "classic", "forever" }, { deDE = { progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Ich kann es nicht fassen, dass Metz ernsthaft erwartet, dass unsere Truppen diesen minderwertigen Mist tragen, um sich gegen die eisigen Angriffe der Geißel zu verteidigen." }, enUS = { progress = "Filling a work order, {class}?", completion = "I still can't believe Metz expects our troops to wear this low-quality garbage to protect against the freezing attacks of the Scourge." } })
apply(9184, { "classic", "forever" }, { deDE = { progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Ganz schön tückisch, diese Dinger..." }, enUS = { progress = "Filling a work order, {class}?", completion = "These are... wicked." } })
apply(9185, { "classic", "forever" }, { deDE = { progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Unverwüstliche Rüstungssets sind vielseitig einsetzbar, {name}. Sie taugen nicht nur als zusätzliche Rüstungsschicht, sondern geben auch hervorragende Teekannenwärmer ab." }, enUS = { progress = "Filling a work order, {class}?", completion = "The rugged armor kits have many uses, {name}. They aren't JUST for slapping on certain armor pieces for added protection. Like this one here, I'm going to use it as teapot cozy." } })
apply(9187, { "classic", "forever" }, { deDE = { progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Die Druiden werden den Aufwand zu Schätzen wissen, welcher zur Herstellung dieser Hosen notwendig war. Vielen Dank, {class}." }, enUS = { progress = "Filling a work order, {class}?", completion = "The druids will definitely appreciate the craftsmanship that went into the making of these pants. Many thanks, {class}." } })
apply(9188, { "classic", "forever" }, { deDE = { progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Bei allen guten Geistern, diese Dinger blenden mich ja fast schon! Verrückt, oder?" }, enUS = { progress = "Filling a work order, {class}?", completion = "I can almost see my reflection in these things! That's crazy." } })
apply(9190, { "classic", "forever" }, { deDE = { progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Bei Bronzebeards Bart! Ihr habt mir tatsächlich Runenstoffstiefel gebracht... Schätze, ich habe diese Wette verloren." }, enUS = { progress = "Filling a work order, {class}?", completion = "By Bronzebeard's beard! You actually brought me runecloth boots... I guess I lost that bet." } })
apply(9191, { "classic", "forever" }, { deDE = { progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Heiliger Schnürsenkel! Ist es das, was ich denke? Unsere Soldaten beschweren sich immer wieder über den Mangel an Taschen, um ihre ganze Ausrüstung zu verstauen. Einer hat sogar seine Feldrationen in seinen Backen verstaut... verdammter Nager.\n\nDas wird die Gemüter bestimmt abkühlen." }, enUS = { progress = "Filling a work order, {class}?", completion = "Blessed bootstraps! Are those what I think they are? The troops have been complaining non-stop about the lack of storage space for all that is required while in the field. One of them even drew me a diagram - such a pansy...\n\nThese will definitely help alleviate some of the whining." } })
apply(9194, { "classic", "forever" }, { deDE = { progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Das war doch völlig unnötig! Nein wirklich, wer hat sich das denn einfallen lassen? Keiner von uns wird ernsthaft beim Sturm auf Naxxramas eine Robe tragen wollen. Was hat Metz sich bloß dabei gedacht?\n\n<Rottenkommandant Stonebruiser seufzt.>\n\nBah, nur wieder eine weitere Ladung unnützes Zeug, das ich an die Front schaffen muss." }, enUS = { progress = "Filling a work order, {class}?", completion = "You shouldn't have! No really, you shouldn't have. I don't know what Metz is thinking, but nobody is going to be wearing these robes into Naxxramas.\n\n<Packmaster Stonebruiser sighs.>\n\nBah, another pile of junk I'll have to get transferred to the front lines and another berating I'll have to take from Chambers." } })
apply(9195, { "classic", "forever" }, { deDE = { progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Jetzt kommen wir der Sache schon näher, {class}. Sachen die ordentlich Krach machen!" }, enUS = { progress = "Filling a work order, {class}?", completion = "Now you're talking my language, {class}. Things that go BOOM!" } })
apply(9196, { "classic", "forever" }, { deDE = { progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Die Herstellung dieser Dinger muss ganz schön kostspielig gewesen sein. Hab ich Recht, {name}?" }, enUS = { progress = "Filling a work order, {class}?", completion = "These must have cost a pretty copper piece to make. Am I right or am I right, {name}?" } })
apply(9198, { "classic", "forever" }, { deDE = { progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Thoriumröhren? Wow, danke.\n\n<Rottenkommandant Stonebruiser wirft den Stapel Thoriumröhren auf einen der vielen Schrotthaufen.>" }, enUS = { progress = "Filling a work order, {class}?", completion = "Thorium tubes? Gee, thanks.\n\n<Packmaster Stonebruiser throws the stack of Thorium tubes into a large pile of assorted junk.>" } })
apply(9200, { "classic", "forever" }, { deDE = { progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Die Nützlichkeit hiervon steht wohl außer Frage." }, enUS = { progress = "Filling a work order, {class}?", completion = "The utility of these should go without saying." } })
apply(9201, { "classic", "forever" }, { deDE = { progress = "Ihr führt einen Auftrag aus, {class}?", completion = "<Rottenkommandant Stonebruiser öffnet einen der großen Arkanschutztränke und nimmt einen kräftigen Schluck.>\n\nWooohooo! Das geht richtig ab, Baby! Aber richtig!" }, enUS = { progress = "Filling a work order, {class}?", completion = "<Packmaster Stonebruiser pops open one of the greater arcane protection potions and take a swig.>\n\nWOOT! These pack a kick, baby! A kick I say!" } })
apply(9202, { "classic", "forever" }, { deDE = { progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Wisst Ihr wie die hier von den Truppen an der Front genannt werden? Priester in der Flasche...\n\n<Rottenkommandant Stonebruiser singt.>\n\n\"I'm your priest in a bott-le baby... you gotta drink me the right way...\"\n\nWas glotzt Ihr so Junge? Der Titel war hier monatelang auf Platz Eins!" }, enUS = { progress = "Filling a work order, {class}?", completion = "Do you know what the troops on the front lines call these? Priests in a bottle...\n\n<Packmaster Stonebruiser sings.>\n\n\"I'm your priest in a bott-le baby... you gotta drink me the right way...\"\n\nWhat's the matter sonny? It's a very popular song around these parts." } })
apply(9204, { "classic", "forever" }, { deDE = { progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Hier hättet hierfür eine andere Verwendung gehabt, nicht wahr? Nun ja, dem Ganzen nachzuweinen hilft auch nicht mehr, {name}." }, enUS = { progress = "Filling a work order, {class}?", completion = "You could have used this for something else, but you didn't, did you? No use crying about it now, {name}." } })
apply(9205, { "classic", "forever" }, { deDE = { progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Ihr wisst wirklich nicht, wofür man die hier braucht?\n\n<Rottenkommandant Stonebruiser lacht.>\n\nAls ob ich Euch das verraten würde!" }, enUS = { progress = "Filling a work order, {class}?", completion = "You really don't know what these are for?\n\n<Packmaster Stonebruiser laughs.>\n\nLike I'm going to tell you!" } })
apply(9206, { "classic", "forever" }, { deDE = { progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Aus denen macht man die besten Aalröllchen in der ganzen Welt. Richtig gehört - IN DER GANZEN WELT." }, enUS = { progress = "Filling a work order, {class}?", completion = "These make the best eel rolls in the world. That's right - IN THE WORLD." } })
apply(9210, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Arkanum?", completion = "Die wertlose Magie in diesen Verzauberungen verstärkt meinen Ärger. Mein Zorn gibt mir Stärke.\n\nBringt mir mehr davon und Ihr werdet einen weiteren Greuelwächter erhalten." }, enUS = { progress = "Do you have the arcanum?", completion = "The worthless magic in these enchantments fuels my anger. My anger gives me strength.\n\nBring me more and you shall receive another Savage Guard." } })
apply(9229, { "classic", "forever" }, { deDE = { progress = "Gibt es Neuigkeiten über Ramaladni?", completion = "Es ist sein Ring! Aber er ist zerstört. Ihr habt keine weiteren Hinweise auf Ramaladni gefunden?\n\n<Korfax verzieht das Gesicht.>\n\nDas verheißt nichts Gutes für Ramaladni. Der Ring jedoch ... er könnte noch nützlich sein." }, enUS = { progress = "Any news of Ramaladni?", completion = "It is his ring! But it is destroyed. No other evidence of Ramaladni was found?\n\n<Korfax grimaces.>\n\nThis does not bode well for Ramaladni. The ring, however... it might be salvageable." } })
apply(9230, { "classic", "forever" }, { deDE = { progress = "Gefrorene Runen findet man wahrscheinlich in Naxxramas.", completion = "Ramaladni selbst könnte es nicht besser gemacht haben! Hier ist der Ring, wie versprochen." }, enUS = { progress = "Frozen runes could probably be found inside Naxxramas.", completion = "Ramaladni himself couldn't have done better! Here is the ring, as promised." } })
apply(9232, { "classic", "forever" }, { deDE = { progress = "Ihr habt nicht zufällig Omarion getroffen?", completion = "<Wilhelm wischt sich den Schweiß von der Stirn.>\n\nDas war ein hartes Stück Arbeit! Ich hoffe, die Hose gefällt Euch, {class}. Zumindest werdet ihr jetzt in einer sauberen Hose sterben." }, enUS = { progress = "You haven't run into Omarion, have you?", completion = "<Wilhelm wipes the sweat from his brow.>\n\nThat's some hard work! Enjoy the pants, {class}. At least you'll die in a clean pair now." } })
apply(9247, { "classic", "forever" }, { deDE = { progress = "Ah, {name}, es ist schön Euch zu sehen.", completion = "Schon dadurch, dass Ihr unseren Ruf beantwortet habt, stehen wir in Eurer Schuld, {name}. Die Argentumdämmerung ist sich sicher, dass Euer leuchtendes Beispiel auch den anderen Kämpfern gezeigt hat, wie man die Geißel zurückwirft!" }, enUS = { progress = "Ah, {name}, it is good to see you.", completion = "Simply by answering the call, we are in your debt, {name}. The Argent Dawn is certain that through your shining example, others that are here to aid us will gain great insight into how best to throw back this Scourge Invasion!" } })
apply(9263, { "classic", "forever" }, { deDE = { progress = "Habt Ihr bereits Nachforschungen angestellt? Uns bleibt keine Zeit zum Trödeln!", completion = "Hmm. Was Eure Nachforschungen betrifft, so scheinen diese Stimmen in den Kreisen... sie scheinen einer Art Kommunikation zu dienen. Mich schaudert es bei dem Gedanken, welch abartige Geister mit Hilfe dieser Magie angerufen werden. Nun ja, Ihr scheint ja in einem Stück davongekommen zu sein. Die Argentumdämmerung schätzt Eure Bemühungen." }, enUS = { progress = "Have you investigated the invasion yet? There's no time for dawdling!", completion = "Hmm. From what you've told me, the voices within the circles... they must be used for communication of some kind. I shudder to think what unnatural minds are contacted through such magic. Regardless, you seem to have emerged whole and sane.  The Argent Dawn appreciates your service." } })
apply(9264, { "classic", "forever" }, { deDE = { progress = "Habt Ihr bereits Nachforschungen angestellt? Uns bleibt keine Zeit zum Trödeln!", completion = "Hmm. Was Eure Nachforschungen betrifft, so scheinen diese Stimmen in den Kreisen... sie scheinen einer Art Kommunikation zu dienen. Mich schaudert es bei dem Gedanken, welch abartige Geister mit Hilfe dieser Magie angerufen werden. Nun ja, Ihr scheint ja in einem Stück davongekommen zu sein. Die Argentumdämmerung schätzt Eure Bemühungen." }, enUS = { progress = "Have you investigated the invasion yet? There's no time for dawdling!", completion = "Hmm. From what you've told me, the voices within the circles... they must be used for communication of some kind. I shudder to think what unnatural minds are contacted through such magic. Regardless, you seem to have emerged whole and sane.  The Argent Dawn appreciates your service." } })
apply(9265, { "classic", "forever" }, { deDE = { progress = "Habt Ihr bereits Nachforschungen angestellt? Uns bleibt keine Zeit zum Trödeln!", completion = "Hmm. Was Eure Nachforschungen betrifft, so scheinen diese Stimmen in den Kreisen... sie scheinen einer Art Kommunikation zu dienen. Mich schaudert es bei dem Gedanken, welch abartige Geister mit Hilfe dieser Magie angerufen werden. Nun ja, Ihr scheint ja in einem Stück davongekommen zu sein. Die Argentumdämmerung schätzt Eure Bemühungen." }, enUS = { progress = "Have you investigated the invasion yet? There's no time for dawdling!", completion = "Hmm. From what you've told me, the voices within the circles... they must be used for communication of some kind. I shudder to think what unnatural minds are contacted through such magic. Regardless, you seem to have emerged whole and sane.  The Argent Dawn appreciates your service." } })
apply(9295, { "classic", "forever" }, { deDE = { progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden." }, enUS = { progress = "Yes? What do you have there?", completion = "How tragic. These words, clearly meant for someone the soldier loved, never made it to their destination. The events detailed happened years ago; I'm not sure if the intended recipient still lives.\n\nThere is hope yet, however. With the names and information he gives, I might be able to locate the family! It will take some research, but the librarian in Stormwind owes me a favor...\n\nThank you for bringing this to me. With your help, we may be able to grant someone peace of mind at last." } })
apply(9299, { "classic", "forever" }, { deDE = { progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden." }, enUS = { progress = "Yes? What do you have there?", completion = "How tragic. These words, clearly meant for someone the soldier loved, never made it to their destination. The events detailed happened years ago; I'm not sure if the intended recipient still lives.\n\nThere is hope yet, however. With the names and information he gives, I might be able to locate the family! It will take some research, but the librarian in Stormwind owes me a favor...\n\nThank you for bringing this to me. With your help, we may be able to grant someone peace of mind at last." } })
