apply(9310, { "classic", "forever" }, { deDE = { progress = "Kann ich Euch irgendwie weiterhelfen?", completion = "Ihr sagt, dass Ihr das bei einer der Kreaturen gefunden habt, die die Stadt angreifen?\n\nWir haben von Basislagern der Nekropole gehört, die die Geißel heraufbeschworen hat. Ich vermute, dass sie eines davon innerhalb von Undercity errichten wollten. Wir müssen zukünftig sehr vorsichtig sein." }, enUS = { progress = "Can I help you with something?", completion = "You say this was taken from a wight attacking the city?\n\nWe have received word about the necropolis base camps that are being summoned by the Scourge. I suspect they were trying to create one in the Undercity. We will have to be vigilant in the future." } })
apply(9322, { "classic", "forever" }, { deDE = { completion = "Euer Geist erstrahlt mit der Wärme der Feuer Kalimdors. Ist die Hitze nicht anregend?\n\nWenn die Macht von Euch schwindet, könnte Euch dies hier vielleicht dabei helfen, das Ganze wieder aufleben zu lassen." }, enUS = { completion = "Your spirit glows with the warmth of the Kalimdor fires, friend. Is the heat not invigorating?\n\n Once the power fades from you, perhaps these will help rekindle the feeling." } })
apply(9323, { "classic", "forever" }, { deDE = { completion = "Ah, da seid Ihr also. Etwas erschöpfter, ein wenig schmutziger, aber erleuchtet! Die Wärme berührt und vereint uns alle während dieser Zeit. Euer Wesen erstrahlt mit der Macht der Feuer, die Ihr berührt habt.\n\nAh, ich vermute, dass Erleuchtung heutzutage wohl eher als eine armselige Belohnung für eine Aufgabe wie diese angesehen wird. Nehmt dies hier, bitte, und genießt das Fest." }, enUS = { completion = "Ah, here you are. A little wearier, a bit dustier, but enlightened! The heat touches us all during this season and unites us; your very being glows with the power of the fires you touched.\n\nAh, but these days enlightenment is taken as a rather poor reward for being sent on a task, I suppose. Take these, then, and enjoy the celebration." } })
apply(9362, { "classic", "forever" }, { deDE = { progress = "Es ist keine Zeit zu verlieren! Habt Ihr die Muschel?", completion = "Mh, diese Muschel wird wahrlich von einer seltsamen Aura umgeben. Es scheint geradezu angebracht, dass Eure Belohnung für die Wiederbeschaffung zum Teil daraus besteht, diese magischen Fähigkeiten zu testen..." }, enUS = { progress = "There is not time to waste!  Have you the shell?", completion = "I must say, this shell has a strange aura.  It seems only fitting that part of your reward for retrieving it would be to test its magical capabilities..." } })
apply(9364, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Magie eingesammelt?", completion = "Wunderbar! Prächtig!\n\nNun sind wir in der Lage, diese Magie zu einem neuen Zauber zu formen. Seht!" }, enUS = { progress = "Have you collected the magic?", completion = "Splendid!  Splendid!\n\nNow we are able to reform this magic into a new spell.  Behold!" } })
apply(9367, { "classic", "forever" }, { deDE = { completion = "Ausgezeichnet! Scheinbar haben wir dieses Jahr pflichtgetreue Flammenbewahrer ernannt, wenn die Freudenfeuer so herrlich brennen, wie Ihr es berichtet. Danke, dass Ihr der Sache für mich nachgegangen seid. Hier, nehmt dies als kleines Zeichen für meine Wertschätzung." }, enUS = { completion = "Excellent! It seems we've appointed dutiful Flamekeepers this year if the bonfires are as well-kept as you claim. Thank you for inspecting them for me; here, take this as a small token of my esteem." } })
apply(9368, { "classic", "forever" }, { deDE = { progress = "Brennen alle Feuer?", completion = "Ausgezeichnet! Scheinbar haben wir dieses Jahr pflichtgetreue Flammenbewahrer ernannt, wenn die Freudenfeuer so herrlich brennen, wie Ihr es berichtet. Danke, dass Ihr der Sache für mich nachgegangen seid. Hier, nehmt dies als kleines Zeichen für meine Wertschätzung." }, enUS = { progress = "Are the fires burning?", completion = "Excellent! It seems we've appointed dutiful Flamekeepers this year if the bonfires are as well-kept as you claim. Thank you for inspecting them for me; here, take this as a small token of my esteem." } })
apply(9388, { "classic", "forever" }, { deDE = { completion = "Ahhh, sie brennen also noch. Das freut mich; es wäre nicht gut, wenn die Feuer vorzeitig erlöschen würden. Ihr habt gute Arbeit geleistet, {name}. Nehmt dies mit meinem Segen." }, enUS = { completion = "Ahhh, so they do still burn. I am glad; it would not do for those fires to burn out before their time. You have done well, {name}. Take this with my blessing." } })
apply(9389, { "classic", "forever" }, { deDE = { completion = "Ihr seid also wieder da und habt die Smaragdflammen dieser Welt gesehen. Was sagt Ihr, mh? Ein mit Sicherheit seltener und wunderschöner Anblick. Natürlich weiß ich, dass eine handfeste Belohnung mehr Anklang findet... also bitte, nehmt dies für Eure Mühen." }, enUS = { completion = "So you've returned, and you've seen to the emerald flames of the continent. What do you think, mm? A rare and wonderful sight, to be certain. I am aware, however, that tangible rewards are better appreciated... so please, take this for your trouble." } })
apply(9415, { "classic", "forever" }, { deDE = { completion = "Die Allianz braucht jeden tauglichen Rekrut, den sie bekommen kann. Die Horde hat ständig Verstärkung vom nördlichen Kontinent bekommen, wir mussten kämpfen, um überhaupt standzuhalten.\n\nLasst Euch die Lage von mir schildern." }, enUS = { completion = "The Alliance needs every able body they can get. The Horde has been receiving a steady supply of reinforcements from the northern part of the continent, and it's been a struggle to keep up.\n\nLet me explain the situation to you." } })
apply(9416, { "classic", "forever" }, { deDE = { completion = "Es ist gut, dass Ihr hier seid, aber wir haben keine Zeit für überflüssige Worte. Was Ihr braucht, sind Anweisungen, und dann müsst Ihr losziehen.\n\nHört gut zu." }, enUS = { completion = "It's good that you're hear, but there's no time to waste making small talk. You need instructions, and then you need to get out there.\n\nListen up." } })
apply(9419, { "classic", "forever" }, { deDE = { completion = "Dem Licht sei Dank, Eure Suche war erfolgreich.\n\nHätten wir nur eher damit begonnen, dann wären wir jetzt nicht in einer so verzweifelten Notlage. Wir müssen verhindern, dass die Schätze der Wüste in die Hände der Horde fallen." }, enUS = { completion = "Thank the Light you were successful.\n\nNow if we could only have started this sooner, our need would not be so desperate. We must keep the bounty of the desert from falling into the hands of the Horde." } })
apply(9422, { "classic", "forever" }, { deDE = { progress = "Hütet Euch vor den Gefahren der Wüste, {name}. Die Allianz könnte hinter jeder Düne lauern und jeder Schritt könnte somit Euer letzter sein.", completion = "Ausgezeichnete Arbeit, {name}. Diese Ressourcen kommen sofort zum Rest der Vorräte. Jedes Bisschen trägt zu unserem Sieg und zur Schwächung unserer Feinde bei." }, enUS = { progress = "Be wary of the dangers of the desert, {name}. With the Alliance lurking in the dunes, any step could be your last.", completion = "You've done well, {name}. These resources will be added to our stockpiles, and every bit is to our gain and our enemy's loss." } })
apply(9665, { "classic", "forever" }, { deDE = { completion = "Das sind gute Neuigkeiten, {name}. Bis wir die Kräfte der Allianz gänzlich vertrieben haben, wird es hier in den Pestländern dauerhaft zu Kämpfen kommen.\n\nIch hoffe, dass Ihr uns bis zu diesem Tag auch noch weiterhin unterstützt." }, enUS = { completion = "This is good news, {name}. It will be a constant struggle here in the Plaguelands until we have fully driven back the forces of the Alliance.\n\nUntil that day, I hope that we will have your continued assistance." } })
